#requires -Version 5.1
# InspektorOfficEr : PC inspection report (WMI) + inventory (remote access IDs, disk protection, PC passport) -> Excel on the flash drive
# GENERATED FILE: edit src\*.ps1 and run build.ps1. Do not edit this file by hand.
# Switches: -SkipReport (inventory only)  -SkipExcel (report only)  -NoRemoteCli  -NoPrompt  -Diagnose (write Raports\_debug\diagnose_*.txt)
param([switch]$SkipReport, [switch]$SkipExcel, [switch]$NoRemoteCli, [switch]$NoPrompt, [switch]$Diagnose)

$ErrorActionPreference = 'Stop'

# ===================== CORE: strings, config, shared state =====================
$AppName = 'InspektorOfficEr'; $AppVer = '1.2.0'

# ---------- Cyrillic-safe strings: sources are pure ASCII, texts are written as \uXXXX ----------
function U([string]$s) { [regex]::Replace($s, '\\u([0-9a-fA-F]{4})', { param($m) [string][char][Convert]::ToInt32($m.Groups[1].Value, 16) }) }

# ---------- configuration ----------
# Import-InspektorConfig <path> : parsed config.json, or $null (file missing / invalid -> built-in defaults)
function Import-InspektorConfig([string]$path) {
    if (-not $path -or -not (Test-Path -LiteralPath $path)) { return $null }
    try { return ([IO.File]::ReadAllText($path, [Text.Encoding]::UTF8) | ConvertFrom-Json) }
    catch { Write-Host "config.json is invalid, built-in defaults are used: $($_.Exception.Message)" -ForegroundColor Yellow; return $null }
}
# Cfg 'section.key' <default> : value from config.json, or the default if the key is missing / empty ($false is a value)
function Cfg([string]$path, $default) {
    $o = $script:Cfg
    foreach ($k in $path.Split('.')) {
        if ($null -eq $o) { return $default }
        $p = $o.PSObject.Properties[$k]
        if (-not $p) { return $default }
        $o = $p.Value
    }
    if ($null -eq $o -or ($o -is [string] -and $o.Trim() -eq '')) { return $default }
    $o
}
# relative paths are resolved against the script folder ($Root)
function RootPath([string]$p) { if ([IO.Path]::IsPathRooted($p)) { $p } else { Join-Path $Root $p } }

function Finish($code) { try { Stop-Transcript | Out-Null } catch { }; exit $code }

# ---------- shared state ----------
$NO = (U '\u041d\u0435\u0442')
$NoId = (U '\u0423\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d, ID \u043d\u0435 \u043d\u0430\u0439\u0434\u0435\u043d')     # product is present, but its ID could not be read (not the same as "none")
$script:Src = @{ Passport = ''; RemoteA = ''; RemoteB = ''; Disk = '' }   # where each value came from (printed to console)

# ===================== LOG, DIAGNOSTICS, EXTERNAL PROCESSES =====================
$script:LogLevels = @{ DEBUG = 0; INFO = 1; WARN = 2; ERROR = 3 }
$script:LogBuf    = New-Object System.Collections.Generic.List[string]

# Write-Log <DEBUG|INFO|WARN|ERROR> <message>
# Every message is kept in memory (it goes to the -Diagnose file); the console shows messages at or above
# config.json log.level (default INFO). With -Diagnose the console shows everything.
function Write-Log([string]$Level, [string]$Message) {
    $lv = $Level.ToUpper()
    if (-not $script:LogLevels.ContainsKey($lv)) { $lv = 'INFO' }
    if ($script:LogBuf.Count -lt 5000) { [void]$script:LogBuf.Add(('{0} [{1}] {2}' -f (Get-Date -Format 'HH:mm:ss.fff'), $lv, $Message)) }
    $min = $script:LogLevels[([string](Cfg 'log.level' 'INFO')).ToUpper()]
    if ($null -eq $min) { $min = 1 }
    if ($Diagnose) { $min = 0 }
    if ($script:LogLevels[$lv] -lt $min) { return }
    $color = 'Gray'
    if ($lv -eq 'ERROR') { $color = 'Red' } elseif ($lv -eq 'WARN') { $color = 'Yellow' } elseif ($lv -eq 'DEBUG') { $color = 'DarkGray' }
    Write-Host ('  [{0}] {1}' -f $lv, $Message) -ForegroundColor $color
}

function Test-IsAdmin {
    try {
        $id = [Security.Principal.WindowsIdentity]::GetCurrent()
        return (New-Object Security.Principal.WindowsPrincipal($id)).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
    } catch { return $false }
}

# CIM query that never throws: a broken WMI class must not kill the whole report (returns an empty array)
function Get-CimSafe {
    try { Get-CimInstance @args }
    catch { Write-Log WARN ('CIM query failed ({0}): {1}' -f (($args | Where-Object { $_ -is [string] -and $_ -notlike '-*' } | Select-Object -First 1)), $_.Exception.Message); @() }
}

# Runs an external program with a hard timeout. Never throws.
# Returns: ExitCode (null on timeout), Stdout, Stderr, TimedOut, Error
function Invoke-External([string]$FilePath, [string]$Arguments = '', [int]$TimeoutSec = 10) {
    $r = [pscustomobject]@{ ExitCode = $null; Stdout = ''; Stderr = ''; TimedOut = $false; Error = '' }
    $p = $null
    try {
        $psi = New-Object Diagnostics.ProcessStartInfo
        $psi.FileName = $FilePath; $psi.Arguments = $Arguments
        $psi.UseShellExecute = $false; $psi.CreateNoWindow = $true
        $psi.RedirectStandardOutput = $true; $psi.RedirectStandardError = $true
        $p = [Diagnostics.Process]::Start($psi)
        # poll both pipes and keep whatever arrived: a child left behind may hold the pipes open after the program exited
        $bo = New-Object char[] 4096; $be = New-Object char[] 4096
        $so = New-Object Text.StringBuilder; $se = New-Object Text.StringBuilder
        $to = $p.StandardOutput.ReadAsync($bo, 0, $bo.Length); $te = $p.StandardError.ReadAsync($be, 0, $be.Length)
        $doneO = $false; $doneE = $false; $exitedAt = $null
        $sw = [Diagnostics.Stopwatch]::StartNew()
        while ($true) {
            if (-not $doneO -and $to.IsCompleted) {
                $n = 0; if (-not $to.IsFaulted) { $n = $to.Result }
                if ($n -gt 0) { [void]$so.Append($bo, 0, $n); $to = $p.StandardOutput.ReadAsync($bo, 0, $bo.Length) } else { $doneO = $true }
            }
            if (-not $doneE -and $te.IsCompleted) {
                $n = 0; if (-not $te.IsFaulted) { $n = $te.Result }
                if ($n -gt 0) { [void]$se.Append($be, 0, $n); $te = $p.StandardError.ReadAsync($be, 0, $be.Length) } else { $doneE = $true }
            }
            if ($p.HasExited -and $null -eq $exitedAt) { $exitedAt = $sw.ElapsedMilliseconds }
            if ($p.HasExited -and $doneO -and $doneE) { break }
            if ($null -ne $exitedAt -and ($sw.ElapsedMilliseconds - $exitedAt) -gt 1000) { break }
            if ($sw.ElapsedMilliseconds -gt ($TimeoutSec * 1000)) {
                $r.TimedOut = $true
                try { $p.Kill() } catch { }
                [void]$p.WaitForExit(2000)
                break
            }
            Start-Sleep -Milliseconds 20
        }
        $r.Stdout = $so.ToString(); $r.Stderr = $se.ToString()
        if (-not $r.TimedOut) { $r.ExitCode = $p.ExitCode }
    } catch { $r.Error = $_.Exception.Message }
    finally { if ($p) { try { $p.Dispose() } catch { } } }
    Write-Log DEBUG ("exec: {0} {1} -> exit={2} timeout={3} error='{4}' stdout={5}b" -f $FilePath, $Arguments, $r.ExitCode, $r.TimedOut, $r.Error, $r.Stdout.Length)
    $r
}

# ---- -Diagnose: environment summary (no user names, no file contents) ----
function Get-EnvironmentInfo {
    $l = @()
    $l += "app            : $AppName $AppVer"
    $l += "powershell     : $($PSVersionTable.PSVersion) (CLR $($PSVersionTable.CLRVersion))"
    $os = @(Get-CimSafe Win32_OperatingSystem | Select-Object -First 1)
    if ($os.Count -and $os[0]) { $l += "os             : $($os[0].Caption) $($os[0].Version) $($os[0].OSArchitecture)" }
    else { $l += "os             : $([Environment]::OSVersion.VersionString) (WMI unavailable)" }
    $v = [Environment]::OSVersion.Version
    $l += "windows 7/2008  : $(($v.Major -eq 6 -and $v.Minor -le 1))"
    $l += "elevated (admin): $(Test-IsAdmin)"
    try { $l += "exec policy    : $(Get-ExecutionPolicy)" } catch { }
    $dt = 'unknown'
    try {
        if ($Drive) {
            $ld = @(Get-CimSafe Win32_LogicalDisk -Filter ("DeviceID='" + $Drive + "'") | Select-Object -First 1)
            if ($ld.Count -and $ld[0]) { $dt = @{ 2 = 'removable'; 3 = 'fixed'; 4 = 'network'; 5 = 'optical' }[[int]$ld[0].DriveType] }
        }
    } catch { }
    $l += "script drive    : $Drive ($dt)"
    $l += "config.json     : $(if ($script:Cfg) { 'loaded' } else { 'not found / invalid (defaults)' })"
    $l += "switches        : SkipReport=$SkipReport SkipExcel=$SkipExcel NoHopCli=$NoRemoteCli NoPrompt=$NoPrompt Diagnose=$Diagnose"
    $l += "features        : hardwareCollector=$(Cfg 'features.hardwareCollector' $true) excel=$(Cfg 'features.excel' $true) remoteAccessDetect=$(Cfg 'features.remoteAccessDetect' $true) remoteAccessCli=$(Cfg 'features.remoteAccessCli' $true) diskProtectionDetect=$(Cfg 'features.diskProtectionDetect' $true)"
    $l += "timeouts (sec)  : remoteCli=$(Cfg 'timeouts.remoteCliSec' 8) robocopy=$(Cfg 'timeouts.robocopySec' 30)"
    $l
}

function Save-DiagnoseLog([string]$dir) {
    $d = Join-Path $dir '_debug'
    New-Item -ItemType Directory -Force $d | Out-Null
    $pc = $env:COMPUTERNAME; if (-not $pc) { $pc = [Environment]::MachineName }
    $f = Join-Path $d ('diagnose_{0}_{1}.txt' -f $pc, (Get-Date -Format 'yyyyMMdd_HHmmss'))
    $lines = @('InspektorOfficEr diagnostic log (safe to share: contains the PC name, no user data)', '') + @(Get-EnvironmentInfo) + @('', '--- log ---') + @($script:LogBuf)
    [IO.File]::WriteAllLines($f, [string[]]$lines, (New-Object Text.UTF8Encoding($true)))
    $f
}

# ===================== CONTEXT: config, switches, paths (runs once at startup) =====================
$Root = $PSScriptRoot
$Cfg  = Import-InspektorConfig (Join-Path $Root 'config.json')

# command-line parameters always win over config.json
if (-not (Cfg 'features.hardwareCollector' $true)) { $SkipReport = [switch]$true }
if (-not (Cfg 'features.excel' $true))        { $SkipExcel = [switch]$true }
if (-not (Cfg 'features.remoteAccessCli' $true)) { $NoRemoteCli  = [switch]$true }
if (-not (Cfg 'passport.askIfMissing' $true)) { $NoPrompt  = [switch]$true }

# -Diagnose collects the full debug log (also keeps the console verbose)
# paths (drive letter is detected from the script location)
$Drive   = Split-Path -Qualifier $Root
$OutDir  = RootPath ([string](Cfg 'paths.reportsDir' 'Raports'))
$PassDir = RootPath ([string](Cfg 'paths.passportsDir' 'Passports'))     # PC passports (pc_info_<PC>.json) are stored here
$Stamp   = Get-Date -Format ([string](Cfg 'reports.dateFormat' 'yyyyMMdd'))
$RptName = ([string](Cfg 'reports.fileName' '{pc}_report_{date}.html')).Replace('{pc}', $env:COMPUTERNAME).Replace('{date}', $Stamp)
if ($RptName -notmatch '\.html$') { $RptName += '.html' }
$Out       = Join-Path $OutDir $RptName
$StartTime = Get-Date

# ===================== QUICK CHECKS: thresholds from config.json (section "checks"), plain wording =====================
function New-Check([string]$Level, [string]$Text, [string]$Action = '') { [pscustomobject]@{ L = $Level; T = $Text; A = $Action } }

function ConvertTo-Date([string]$s) {
    try { [datetime]::ParseExact($s, 'yyyy-MM-dd', [Globalization.CultureInfo]::InvariantCulture) } catch { $null }
}

# End of support by Windows build (Microsoft lifecycle pages). Home/Pro and Enterprise/Education differ for Windows 11.
# Fix or extend in config.json: "checks": { "osSupport": [ { "build": "26200", "home": "2027-10-12", "ent": "2028-10-10" } ] }
# Returns a date, $null when unknown (then no claim is made). A date before 2010 means "ended long ago".
function Get-OsSupportEnd($os) {
    $cap = [string]$os.Caption; $b = 0
    [void][int]::TryParse([string]$os.BuildNumber, [ref]$b)
    if ($b -le 0 -or $cap -notmatch 'Windows (10|11)') { return $null }
    $isEnt = ($cap -match 'Enterprise|Education|IoT')
    foreach ($e in @(Cfg 'checks.osSupport' @())) {
        if ([string]$e.build -eq [string]$b) {
            $s = $(if ($isEnt -and $e.ent) { [string]$e.ent } else { [string]$e.home })
            $d = ConvertTo-Date $s; if ($d) { return $d }
        }
    }
    if ($b -lt 22000) {                      # Windows 10
        if ($cap -match 'LTSC|LTSB') {
            $lt = @{ 14393 = '2026-10-13'; 17763 = '2029-01-09'; 19044 = '2027-01-12' }
            $s = $lt[$b]
            if ($b -eq 19044 -and $cap -match 'IoT') { $s = '2032-01-13' }
        }
        elseif ($b -ge 19045) { $s = '2025-10-14' }
        else { $s = '2000-01-01' }
        if (-not $s) { return $null }
        return (ConvertTo-Date $s)
    }
    $w11 = @{ 22000 = @('2023-10-10', '2024-10-08'); 22621 = @('2024-10-08', '2025-10-14'); 22631 = @('2025-11-11', '2026-11-10'); 26100 = @('2026-10-13', '2027-10-12') }
    $p = $w11[$b]
    if (-not $p) { return $null }
    $s = $(if ($isEnt) { $p[1] } else { $p[0] })
    ConvertTo-Date $s
}

function Get-OsSupportCheck($os) {
    $cap = ([string]$os.Caption).Trim()
    if (-not $cap) { return $null }
    if ($cap -match 'Windows (7|8|Vista|XP)|2003|2008|Server 2012') {
        return (New-Check 'bad' ((U '\u0423\u0441\u0442\u0430\u0440\u0435\u0432\u0448\u0430\u044f \u041e\u0421 \u0431\u0435\u0437 \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0438: ') + $cap) (U '\u041e\u0431\u043d\u043e\u0432\u0438\u0442\u044c \u0438\u043b\u0438 \u0437\u0430\u043c\u0435\u043d\u0438\u0442\u044c \u041e\u0421 (\u0431\u0435\u0437 \u043e\u0431\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u0439 \u0431\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u043e\u0441\u0442\u0438 \u043f\u043e\u0432\u044b\u0448\u0435\u043d \u0440\u0438\u0441\u043a \u0432\u0437\u043b\u043e\u043c\u0430)'))
    }
    $end = Get-OsSupportEnd $os
    if (-not $end) { return (New-Check 'ok' ((U '\u041e\u0421: ') + $cap)) }
    $warnDays = [int](Cfg 'checks.osSupportWarnDays' 90)
    $days = [int][math]::Floor(($end - (Get-Date).Date).TotalDays)
    $act = U '\u041e\u0431\u043d\u043e\u0432\u0438\u0442\u044c Windows \u0434\u043e \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0435\u043c\u043e\u0439 \u0432\u0435\u0440\u0441\u0438\u0438 (\u0435\u0441\u043b\u0438 \u043e\u0444\u043e\u0440\u043c\u043b\u0435\u043d\u0430 \u043f\u043b\u0430\u0442\u043d\u0430\u044f \u043f\u0440\u043e\u0434\u043b\u0451\u043d\u043d\u0430\u044f \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0430 - \u044d\u0442\u043e \u043c\u043e\u0436\u043d\u043e \u0438\u0433\u043d\u043e\u0440\u0438\u0440\u043e\u0432\u0430\u0442\u044c)'
    if ($days -lt 0) {
        $when = $(if ($end.Year -ge 2010) { ' ' + $end.ToString('dd.MM.yyyy') } else { '' })
        return (New-Check 'bad' (((U '\u041f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0430 \u044d\u0442\u043e\u0439 \u0432\u0435\u0440\u0441\u0438\u0438 Windows \u0437\u0430\u043a\u043e\u043d\u0447\u0438\u043b\u0430\u0441\u044c') + $when + ': ') + $cap) $act)
    }
    if ($days -le $warnDays) {
        return (New-Check 'warn' (((U '\u041f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0430 \u044d\u0442\u043e\u0439 \u0432\u0435\u0440\u0441\u0438\u0438 Windows \u0437\u0430\u043a\u043e\u043d\u0447\u0438\u0442\u0441\u044f ') + $end.ToString('dd.MM.yyyy') + (U ' (\u0447\u0435\u0440\u0435\u0437 ') + $days + (U ' \u0434\u043d.): ')) + $cap) $act)
    }
    New-Check 'ok' ((U '\u041e\u0421 \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0435\u0442\u0441\u044f \u0434\u043e ') + $end.ToString('dd.MM.yyyy') + ': ' + $cap)
}

# SecurityCenter2 productState: 3 bytes as hex. Middle byte high nibble 1 = protection on, last byte not 00 = signatures out of date.
# (decoding is the widely used one, requires a test on real Windows 7/10/11 PCs)
function Get-AvCheck {
    $items = @()
    try { $items = @(Get-CimInstance -Namespace root/SecurityCenter2 -ClassName AntiVirusProduct -ErrorAction Stop) }
    catch { Write-Log DEBUG "report: SecurityCenter2 unavailable: $($_.Exception.Message)" }
    $list = @()
    foreach ($p in $items) {
        $name = ([string]$p.displayName).Trim(); if (-not $name) { continue }
        $st = [int64]0; try { $st = [int64]$p.productState } catch { }
        $hex = '{0:X6}' -f $st
        Write-Log DEBUG ('av: {0} productState=0x{1}' -f $name, $hex)
        $list += [pscustomobject]@{ Name = $name; On = ($hex.Substring(2, 1) -eq '1'); Old = ($hex.Substring(4, 2) -ne '00') }
    }
    if (-not $list.Count) {
        try { if ((Get-Service WinDefend -ErrorAction Stop).Status -eq 'Running') { $list = @([pscustomobject]@{ Name = 'Windows Defender'; On = $true; Old = $false }) } } catch { }
    }
    $act = @($list | Where-Object { $_.On })
    $names = @($(if ($act.Count) { $act } else { $list }) | ForEach-Object { $_.Name } | Select-Object -Unique)
    $script:LastAvNames = $names
    $third = (@($act | Where-Object { $_.Name -notmatch 'Defender' }).Count -gt 0)
    if (-not $list.Count) {
        $c = New-Check 'warn' (U '\u0410\u043d\u0442\u0438\u0432\u0438\u0440\u0443\u0441 \u043d\u0435 \u043e\u0431\u043d\u0430\u0440\u0443\u0436\u0435\u043d') (U '\u041f\u0440\u043e\u0432\u0435\u0440\u0438\u0442\u044c \u0437\u0430\u0449\u0438\u0442\u0443 \u0432\u0440\u0443\u0447\u043d\u0443\u044e (\u043d\u0430 \u0441\u0435\u0440\u0432\u0435\u0440\u0430\u0445 \u0438 \u0441 \u043d\u0435\u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u043d\u043e\u0439 \u0437\u0430\u0449\u0438\u0442\u043e\u0439 \u0441\u0432\u0435\u0434\u0435\u043d\u0438\u044f \u043c\u043e\u0433\u0443\u0442 \u0431\u044b\u0442\u044c \u043d\u0435\u0434\u043e\u0441\u0442\u0443\u043f\u043d\u044b)')
    }
    elseif (-not $act.Count) {
        $c = New-Check 'bad' ((U '\u0410\u043d\u0442\u0438\u0432\u0438\u0440\u0443\u0441 \u0435\u0441\u0442\u044c, \u043d\u043e \u0432\u044b\u043a\u043b\u044e\u0447\u0435\u043d: ') + ($names -join ', ')) (U '\u0412\u043a\u043b\u044e\u0447\u0438\u0442\u044c \u0437\u0430\u0449\u0438\u0442\u0443')
    }
    elseif (@($act | Where-Object { $_.Old }).Count) {
        $c = New-Check 'warn' ((U '\u0410\u043d\u0442\u0438\u0432\u0438\u0440\u0443\u0441: ') + ($names -join ', ') + (U ' \u2014 \u0431\u0430\u0437\u044b \u0443\u0441\u0442\u0430\u0440\u0435\u043b\u0438')) (U '\u041e\u0431\u043d\u043e\u0432\u0438\u0442\u044c \u0430\u043d\u0442\u0438\u0432\u0438\u0440\u0443\u0441\u043d\u044b\u0435 \u0431\u0430\u0437\u044b')
    }
    else { $c = New-Check 'ok' ((U '\u0410\u043d\u0442\u0438\u0432\u0438\u0440\u0443\u0441: ') + ($names -join ', ')) }
    [pscustomobject]@{ Check = $c; Third = $third }
}

# Get-NetFirewallProfile is missing on Windows 7: fall back to the registry policy keys; unknown -> no check (nothing is invented)
function Get-FirewallCheck([bool]$thirdPartyAv) {
    $off = $null
    try { $off = @(Get-NetFirewallProfile -ErrorAction Stop | Where-Object { "$($_.Enabled)" -eq 'False' } | ForEach-Object { [string]$_.Name }) }
    catch { Write-Log DEBUG "report: Get-NetFirewallProfile unavailable: $($_.Exception.Message)" }
    $total = 3
    if ($null -eq $off) {
        $off = @(); $seen = 0
        $base = 'HKLM:\SYSTEM\CurrentControlSet\Services\SharedAccess\Parameters\FirewallPolicy\'
        foreach ($pr in @(@('DomainProfile', 'Domain'), @('StandardProfile', 'Private'), @('PublicProfile', 'Public'))) {
            try {
                $v = (Get-ItemProperty -LiteralPath ($base + $pr[0]) -ErrorAction Stop).EnableFirewall
                if ($null -ne $v) { $seen++; if ([int]$v -eq 0) { $off += $pr[1] } }
            } catch { Write-Log DEBUG "report: firewall registry $($pr[0]): $($_.Exception.Message)" }
        }
        if (-not $seen) { return $null }
    }
    if (-not $off.Count) { return (New-Check 'ok' (U '\u0411\u0440\u0430\u043d\u0434\u043c\u0430\u0443\u044d\u0440 Windows \u0432\u043a\u043b\u044e\u0447\u0451\u043d')) }
    $txt = (U '\u0411\u0440\u0430\u043d\u0434\u043c\u0430\u0443\u044d\u0440 Windows \u0432\u044b\u043a\u043b\u044e\u0447\u0435\u043d \u0432 \u043f\u0440\u043e\u0444\u0438\u043b\u044f\u0445: ') + ($off -join ', ')
    if ($thirdPartyAv) { return (New-Check 'warn' ($txt + (U ' (\u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e, \u0435\u0433\u043e \u0437\u0430\u043c\u0435\u043d\u044f\u0435\u0442 \u0441\u0442\u043e\u0440\u043e\u043d\u043d\u044f\u044f \u0437\u0430\u0449\u0438\u0442\u0430)')) (U '\u041f\u0440\u043e\u0432\u0435\u0440\u0438\u0442\u044c, \u0447\u0442\u043e \u0441\u0435\u0442\u0435\u0432\u0443\u044e \u0437\u0430\u0449\u0438\u0442\u0443 \u0432\u0435\u0434\u0451\u0442 \u0434\u0440\u0443\u0433\u0430\u044f \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u0430')) }
    $lvl = $(if ($off.Count -ge $total) { 'bad' } else { 'warn' })
    New-Check $lvl $txt (U '\u0412\u043a\u043b\u044e\u0447\u0438\u0442\u044c \u0431\u0440\u0430\u043d\u0434\u043c\u0430\u0443\u044d\u0440 Windows')
}

function Get-SysDiskCheck($v) {
    $thrBad = [int](Cfg 'checks.diskFreePctBad' 10); $thrWarn = [int](Cfg 'checks.diskFreePctWarn' 20); $gbBad = [double](Cfg 'checks.diskFreeGbBad' 5)
    $pct = [int][math]::Round(100 * $v.FreeSpace / $v.Size); $gb = [math]::Round($v.FreeSpace / 1GB, 1)
    $txt = ((U '\u0421\u0432\u043e\u0431\u043e\u0434\u043d\u043e \u043d\u0430 \u0441\u0438\u0441\u0442\u0435\u043c\u043d\u043e\u043c \u0434\u0438\u0441\u043a\u0435: {0} \u0413\u0411 ({1}%)') -f $gb, $pct)
    $act = U '\u041e\u0447\u0438\u0441\u0442\u0438\u0442\u044c \u0434\u0438\u0441\u043a (\u0432\u0440\u0435\u043c\u0435\u043d\u043d\u044b\u0435 \u0444\u0430\u0439\u043b\u044b, \u043d\u0435\u043d\u0443\u0436\u043d\u044b\u0435 \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u044b) \u0438\u043b\u0438 \u0437\u0430\u043c\u0435\u043d\u0438\u0442\u044c \u043d\u0430 \u0431\u043e\u043b\u044c\u0448\u0438\u0439'
    if ($pct -lt $thrBad -or $gb -lt $gbBad) { return (New-Check 'bad' ((U '\u0421\u0438\u0441\u0442\u0435\u043c\u043d\u044b\u0439 \u0434\u0438\u0441\u043a \u043f\u043e\u0447\u0442\u0438 \u0437\u0430\u043f\u043e\u043b\u043d\u0435\u043d. ') + $txt) $act) }
    if ($pct -lt $thrWarn) { return (New-Check 'warn' ((U '\u041d\u0430 \u0441\u0438\u0441\u0442\u0435\u043c\u043d\u043e\u043c \u0434\u0438\u0441\u043a\u0435 \u043c\u0430\u043b\u043e \u043c\u0435\u0441\u0442\u0430. ') + $txt) $act) }
    New-Check 'ok' $txt
}

function Get-QuickChecks($os, $up, [double]$ramTotal) {
    $r = @()
    $upWarn = [int](Cfg 'checks.uptimeDaysWarn' 30)
    if ($up.TotalDays -gt 20000) { Write-Log DEBUG 'report: boot time unknown, uptime check skipped' }
    elseif ($up.Days -gt $upWarn) { $r += (New-Check 'warn' ((U '\u041a\u043e\u043c\u043f\u044c\u044e\u0442\u0435\u0440 \u043d\u0435 \u043f\u0435\u0440\u0435\u0437\u0430\u0433\u0440\u0443\u0436\u0430\u043b\u0441\u044f ') + $up.Days + (U ' \u0434\u043d.')) (U '\u041f\u0435\u0440\u0435\u0437\u0430\u0433\u0440\u0443\u0437\u0438\u0442\u044c \u041f\u041a (\u043f\u0440\u0438\u043c\u0435\u043d\u044f\u0442\u0441\u044f \u043e\u0431\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u044f, \u043e\u0441\u0432\u043e\u0431\u043e\u0436\u0434\u0430\u0435\u0442\u0441\u044f \u043f\u0430\u043c\u044f\u0442\u044c)')) }
    else { $r += (New-Check 'ok' ((U '\u0412\u0440\u0435\u043c\u044f \u0440\u0430\u0431\u043e\u0442\u044b \u0431\u0435\u0437 \u043f\u0435\u0440\u0435\u0437\u0430\u0433\u0440\u0443\u0437\u043a\u0438: ') + $up.Days + (U ' \u0434\u043d.'))) }
    $ramWarn = [double](Cfg 'checks.ramGbWarn' 4)
    if ($ramTotal -le 0) { Write-Log DEBUG 'report: RAM size unknown, RAM check skipped' }
    elseif ($ramTotal -lt $ramWarn) { $r += (New-Check 'warn' ((U '\u041c\u0430\u043b\u043e \u043e\u043f\u0435\u0440\u0430\u0442\u0438\u0432\u043d\u043e\u0439 \u043f\u0430\u043c\u044f\u0442\u0438: ') + $ramTotal + (U ' \u0413\u0411')) (U '\u0414\u043e\u0431\u0430\u0432\u0438\u0442\u044c \u043f\u0430\u043c\u044f\u0442\u044c, \u0435\u0441\u043b\u0438 \u041f\u041a \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442 \u043c\u0435\u0434\u043b\u0435\u043d\u043d\u043e')) }
    else { $r += (New-Check 'ok' ((U '\u041e\u043f\u0435\u0440\u0430\u0442\u0438\u0432\u043d\u043e\u0439 \u043f\u0430\u043c\u044f\u0442\u0438 \u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e: ') + $ramTotal + (U ' \u0413\u0411'))) }
    $oc = Get-OsSupportCheck $os; if ($oc) { $r += $oc }
    $av = Get-AvCheck; $r += $av.Check
    $fw = Get-FirewallCheck $av.Third; if ($fw) { $r += $fw }
    $r
}

function ConvertTo-CheckHtml($checks) {
    $lbl = @{ bad = (U '\u0418\u0441\u043f\u0440\u0430\u0432\u0438\u0442\u044c'); warn = (U '\u0412\u043d\u0438\u043c\u0430\u043d\u0438\u0435'); ok = (U '\u041d\u043e\u0440\u043c\u0430') }
    $sb = New-Object Text.StringBuilder
    [void]$sb.Append('<ul class="checks">')
    foreach ($lv in 'bad', 'warn', 'ok') {
        foreach ($c in @($checks | Where-Object { $_.L -eq $lv })) {
            $a = ''; if ($c.A -and $lv -ne 'ok') { $a = '<small class="act">' + (Enc $c.A) + '</small>' }
            [void]$sb.Append('<li class="' + $lv + '"><i aria-hidden="true"></i><span class="lv">' + $lbl[$lv] + '</span><span class="tx">' + (Enc $c.T) + $a + '</span></li>')
        }
    }
    [void]$sb.Append('</ul>')
    $sb.ToString()
}

# one-line answer to "what to fix first"
function Get-CheckLead($checks) {
    $f = @($checks | Where-Object { $_.L -eq 'bad' } | Select-Object -First 1)
    $lv = 'bad'
    if (-not $f.Count) { $f = @($checks | Where-Object { $_.L -eq 'warn' } | Select-Object -First 1); $lv = 'warn' }
    if (-not $f.Count) { return '<p class="lead ok">' + (Enc (U '\u041a\u0440\u0438\u0442\u0438\u0447\u043d\u044b\u0445 \u043f\u0440\u043e\u0431\u043b\u0435\u043c \u043d\u0435 \u043d\u0430\u0439\u0434\u0435\u043d\u043e')) + '</p>' }
    $t = (U '\u0421\u043d\u0430\u0447\u0430\u043b\u0430: ') + $f[0].T
    if ($f[0].A) { $t += ' - ' + $f[0].A }
    '<p class="lead ' + $lv + '">' + (Enc $t) + '</p>'
}

# ===================== CHANGES SINCE THE PREVIOUS REPORT OF THIS PC (snapshot in Raports\_state\<PC>.json) =====================
function Get-SnapshotFile { Join-Path (Join-Path $OutDir '_state') ((([string]$env:COMPUTERNAME) -replace '[^\w\.-]', '_') + '.json') }

function Read-Snapshot {
    $f = Get-SnapshotFile
    if (-not (Test-Path -LiteralPath $f)) { return $null }
    try { return ([IO.File]::ReadAllText($f, [Text.Encoding]::UTF8) | ConvertFrom-Json) }
    catch { Write-Log WARN "snapshot is unreadable, comparison skipped: $($_.Exception.Message)"; return $null }
}

function Save-Snapshot($snap) {
    try {
        $f = Get-SnapshotFile
        New-Item -ItemType Directory -Force (Split-Path $f) | Out-Null
        [IO.File]::WriteAllText($f, ($snap | ConvertTo-Json -Depth 4), (New-Object Text.UTF8Encoding($true)))
    } catch { Write-Log WARN "snapshot not saved: $($_.Exception.Message)" }
}

# $sw / $dsk are the report tables: first column = name, second = version (for software)
function New-Snapshot($os, [double]$ramTotal, $vols, $dsk, $sw) {
    $sv = @($vols | Where-Object { $_.DeviceID -eq $env:SystemDrive } | Select-Object -First 1)
    $free = 0; if ($sv.Count -and $sv[0].Size) { $free = [math]::Round($sv[0].FreeSpace / 1GB, 1) }
    $names = @(); $vers = @()
    foreach ($s in @($sw)) { $p = @($s.PSObject.Properties); $names += [string]$p[0].Value; $vers += [string]$p[1].Value }
    $dn = @(); foreach ($d in @($dsk)) { $p = @($d.PSObject.Properties); if ($p.Count) { $dn += [string]$p[0].Value } }
    [ordered]@{
        Date = (Get-Date -Format 'yyyy-MM-dd HH:mm'); Os = ('{0} build {1}' -f ([string]$os.Caption).Trim(), $os.BuildNumber)
        RamGb = $ramTotal; SysFreeGb = $free; Disks = $dn; Av = @($script:LastAvNames | Where-Object { $_ }); SwN = $names; SwV = $vers
    }
}

function Join-Limited($arr, [int]$max = 40) {
    $a = @($arr); $s = ($a | Select-Object -First $max) -join ', '
    if ($a.Count -gt $max) { $s += (U ' ... \u0438 \u0435\u0449\u0451 ') + ($a.Count - $max) }
    $s
}

function Get-ChangesHtml($old, $cur) {
    if (-not $old) { return '<p class="muted">' + (Enc (U '\u041f\u0435\u0440\u0432\u044b\u0439 \u043e\u0442\u0447\u0451\u0442 \u043f\u043e \u044d\u0442\u043e\u043c\u0443 \u041f\u041a: \u0441\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u0442\u044c \u043f\u043e\u043a\u0430 \u043d\u0435 \u0441 \u0447\u0435\u043c.')) + '</p>' }
    $li = New-Object Collections.ArrayList
    $add = { param($h, $t) [void]$li.Add('<li><b>' + (Enc $h) + '</b>' + (Enc $t) + '</li>') }
    if ([string]$old.Os -ne [string]$cur.Os) { & $add ((U '\u041e\u0421: ')) ("$($old.Os) -> $($cur.Os)") }
    if ([math]::Abs([double]$old.RamGb - [double]$cur.RamGb) -ge 0.2) { & $add (U '\u041e\u0417\u0423: ') ("$($old.RamGb) -> $($cur.RamGb) " + (U '\u0413\u0411')) }
    $dFree = [double]$cur.SysFreeGb - [double]$old.SysFreeGb
    if ($old.SysFreeGb -and [math]::Abs($dFree) -ge [double](Cfg 'checks.changeFreeGb' 5)) { & $add (U '\u0421\u0432\u043e\u0431\u043e\u0434\u043d\u043e \u043d\u0430 \u0441\u0438\u0441\u0442\u0435\u043c\u043d\u043e\u043c \u0434\u0438\u0441\u043a\u0435: ') ("$($old.SysFreeGb) -> $($cur.SysFreeGb) " + (U '\u0413\u0411')) }
    foreach ($pair in @(@('Disks', (U '\u041d\u0430\u043a\u043e\u043f\u0438\u0442\u0435\u043b\u0438')), @('Av', (U '\u0410\u043d\u0442\u0438\u0432\u0438\u0440\u0443\u0441')))) {
        $o = @($old.($pair[0]) | Where-Object { $_ }); $n = @($cur.($pair[0]) | Where-Object { $_ })
        $plus = @($n | Where-Object { $o -notcontains $_ }); $minus = @($o | Where-Object { $n -notcontains $_ })
        if ($plus.Count)  { & $add ($pair[1] + (U ' \u2014 \u043d\u043e\u0432\u044b\u0435: ')) ($plus -join ', ') }
        if ($minus.Count) { & $add ($pair[1] + (U ' \u2014 \u043f\u0440\u043e\u043f\u0430\u043b\u0438: ')) ($minus -join ', ') }
    }
    $om = @{}; $on = @($old.SwN); $ov = @($old.SwV)
    for ($i = 0; $i -lt $on.Count; $i++) { $om[[string]$on[$i]] = [string]$ov[$i] }
    $nm = @{}; $cn = @($cur.SwN); $cv = @($cur.SwV)
    for ($i = 0; $i -lt $cn.Count; $i++) { $nm[[string]$cn[$i]] = [string]$cv[$i] }
    $new = @($nm.Keys | Where-Object { -not $om.ContainsKey($_) } | Sort-Object)
    $gone = @($om.Keys | Where-Object { -not $nm.ContainsKey($_) } | Sort-Object)
    $upd = @($nm.Keys | Where-Object { $om.ContainsKey($_) -and $om[$_] -ne $nm[$_] } | Sort-Object | ForEach-Object { "$_ ($($om[$_]) -> $($nm[$_]))" })
    if ($new.Count)  { & $add ((U '\u0423\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u044b \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u044b') + " ($($new.Count)): ") (Join-Limited $new) }
    if ($gone.Count) { & $add ((U '\u0423\u0434\u0430\u043b\u0435\u043d\u044b \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u044b') + " ($($gone.Count)): ") (Join-Limited $gone) }
    if ($upd.Count)  { & $add ((U '\u041e\u0431\u043d\u043e\u0432\u043b\u0435\u043d\u044b \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u044b') + " ($($upd.Count)): ") (Join-Limited $upd 25) }
    $head = '<p class="muted">' + (Enc ((U '\u0421\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u0441 \u043e\u0442\u0447\u0451\u0442\u043e\u043c \u043e\u0442 ') + [string]$old.Date)) + '</p>'
    if (-not $li.Count) { return $head + '<p>' + (Enc (U '\u0418\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u0439 \u043d\u0435 \u043e\u0431\u043d\u0430\u0440\u0443\u0436\u0435\u043d\u043e.')) + '</p>' }
    $head + '<ul class="chg">' + ($li -join '') + '</ul>'
}

# ===================== REPORT (pure WMI/CIM, self-contained HTML) =====================
function Enc($s) { [System.Net.WebUtility]::HtmlEncode(([string]$s).Trim()) }
function Icon([string]$n) {
    $p = @{
        cpu    = '<rect x="6" y="6" width="12" height="12" rx="2"/><path d="M9 2v4M15 2v4M9 18v4M15 18v4M2 9h4M2 15h4M18 9h4M18 15h4"/>'
        ram    = '<rect x="2" y="7" width="20" height="10" rx="2"/><path d="M6 11v2M10 11v2M14 11v2M18 11v2"/>'
        disk   = '<ellipse cx="12" cy="6" rx="8" ry="3"/><path d="M4 6v6c0 1.7 3.6 3 8 3s8-1.3 8-3V6M4 12v6c0 1.7 3.6 3 8 3s8-1.3 8-3v-6"/>'
        gpu    = '<rect x="2" y="6" width="20" height="11" rx="2"/><circle cx="9" cy="11.5" r="2.5"/><path d="M15 9h4M15 12h4M6 20h12"/>'
        net    = '<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c3 3.5 3 14.5 0 18M12 3c-3 3.5-3 14.5 0 18"/>'
        shield = '<path d="M12 3l8 3v6c0 5-3.5 8-8 9-4.5-1-8-4-8-9V6z"/><path d="M9 12l2 2 4-4"/>'
        apps   = '<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>'
        info   = '<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7.5v.01"/>'
        pulse  = '<path d="M3 12h4l3-7 4 14 3-7h4"/>'
    }
    '<svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">' + $p[$n] + '</svg>'
}
function Card([string]$title, [string]$icon, [string]$body, [string]$cls = '') {
    '<section class="card ' + $cls + '"><h2>' + (Icon $icon) + '<span>' + $title + '</span></h2>' + $body + '</section>'
}
function HtmlTbl($rows, [string]$id = '') {
    $rows = @($rows | Where-Object { $_ })
    if (-not $rows) { return '<p class="muted">' + (U '\u041d\u0435\u0442 \u0434\u0430\u043d\u043d\u044b\u0445') + '</p>' }
    $cols = @($rows[0].PSObject.Properties.Name)
    $sb = New-Object Text.StringBuilder
    [void]$sb.Append('<div class="scroll"><table class="tbl"' + $(if ($id) { ' id="' + $id + '"' } else { '' }) + '><thead><tr>')
    foreach ($c in $cols) { [void]$sb.Append('<th scope="col">' + (Enc $c) + '</th>') }
    [void]$sb.Append('</tr></thead><tbody>')
    foreach ($r in $rows) {       # StringBuilder: 500+ rows stay fast
        [void]$sb.Append('<tr>')
        foreach ($c in $cols) { [void]$sb.Append('<td>' + (Enc $r.$c) + '</td>') }
        [void]$sb.Append('</tr>')
    }
    [void]$sb.Append('</tbody></table></div>')
    $sb.ToString()
}
function KvList($pairs) {
    '<dl class="kv">' + (($pairs.GetEnumerator() | Where-Object { "$($_.Value)".Trim() } | ForEach-Object { '<div><dt>' + (Enc $_.Key) + '</dt><dd>' + (Enc $_.Value) + '</dd></div>' }) -join '') + '</dl>'
}

function New-InspectorReport($path) {
    $cs   = Get-CimSafe Win32_ComputerSystem
    $os   = Get-CimSafe Win32_OperatingSystem
    $bb   = Get-CimSafe Win32_BaseBoard
    $bios = Get-CimSafe Win32_BIOS
    $skipDisk = -1
    try { $skipDisk = (Get-Partition -DriveLetter $Drive.TrimEnd(':') | Get-Disk).Number } catch { Write-Log DEBUG "report: cannot tell which disk is the USB drive: $($_.Exception.Message)" }
    $up = [TimeSpan]::FromDays(99999); if ($os.LastBootUpTime) { $up = (Get-Date) - $os.LastBootUpTime }      # unknown boot time (WMI failed) must not look like a long uptime
    $checks = New-Object System.Collections.ArrayList
    $add = { param($lvl, $txt) [void]$checks.Add([pscustomobject]@{ L = $lvl; T = $txt; A = '' }) }
    $thrBad = [int](Cfg 'checks.diskFreePctBad' 10); $thrWarn = [int](Cfg 'checks.diskFreePctWarn' 20)      # volume bars use the same thresholds as the quick check

    # ---- hardware ----
    $cpuRows = @(Get-CimSafe Win32_Processor)
    $cpuName = ($cpuRows | Select-Object -First 1).Name -replace '\s+', ' '
    $cpu = $cpuRows | Select-Object @{n = (U '\u041f\u0440\u043e\u0446\u0435\u0441\u0441\u043e\u0440'); e = { $_.Name -replace '\s+', ' ' } }, @{n = (U '\u042f\u0434\u0435\u0440'); e = { $_.NumberOfCores } }, @{n = (U '\u041f\u043e\u0442\u043e\u043a\u043e\u0432'); e = { $_.NumberOfLogicalProcessors } }, @{n = (U '\u041c\u0413\u0446'); e = { $_.MaxClockSpeed } }
    $mem = @(Get-CimSafe Win32_PhysicalMemory)
    $ramTotal = [math]::Round($cs.TotalPhysicalMemory / 1GB, 1)
    $ram = $mem | Select-Object @{n = (U '\u0421\u043b\u043e\u0442'); e = { $_.BankLabel } }, @{n = (U '\u041f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044c'); e = { $_.Manufacturer } }, @{n = (U '\u041f\u0430\u0440\u0442-\u043d\u043e\u043c\u0435\u0440'); e = { $_.PartNumber } }, @{n = (U '\u0413\u0411'); e = { [math]::Round($_.Capacity / 1GB, 1) } }, @{n = (U '\u041c\u0413\u0446'); e = { $_.Speed } }
    $dsk = $null
    try {
        $dsk = @(Get-PhysicalDisk -ErrorAction Stop | Where-Object { [int]$_.DeviceId -ne $skipDisk } | Select-Object @{n = (U '\u041c\u043e\u0434\u0435\u043b\u044c'); e = { $_.FriendlyName } }, @{n = (U '\u0422\u0438\u043f'); e = { $_.MediaType } }, @{n = (U '\u0421\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u0435'); e = { $_.HealthStatus } }, @{n = (U '\u0413\u0411'); e = { [math]::Round($_.Size / 1GB) } }, @{n = (U '\u0428\u0438\u043d\u0430'); e = { $_.BusType } })
        foreach ($d in $dsk) { if ("$($d.(U '\u0421\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u0435'))" -notmatch 'Healthy|^$') { & $add 'bad' ((U '\u041d\u0430\u043a\u043e\u043f\u0438\u0442\u0435\u043b\u044c \u0441\u043e\u043e\u0431\u0449\u0430\u0435\u0442 \u043e \u043f\u0440\u043e\u0431\u043b\u0435\u043c\u0435: ') + $d.(U '\u041c\u043e\u0434\u0435\u043b\u044c')) } }
    } catch {
        $dsk = @(Get-CimSafe Win32_DiskDrive | Where-Object { $_.Index -ne $skipDisk } | Select-Object @{n = (U '\u041c\u043e\u0434\u0435\u043b\u044c'); e = { $_.Model } }, @{n = (U '\u0421\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u0435'); e = { $_.Status } }, @{n = (U '\u0413\u0411'); e = { [math]::Round($_.Size / 1GB) } }, @{n = (U '\u0428\u0438\u043d\u0430'); e = { $_.InterfaceType } })
        foreach ($d in $dsk) { if ("$($d.(U '\u0421\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u0435'))" -notmatch '^OK$|^$') { & $add 'bad' ((U '\u041d\u0430\u043a\u043e\u043f\u0438\u0442\u0435\u043b\u044c \u0441\u043e\u043e\u0431\u0449\u0430\u0435\u0442 \u043e \u043f\u0440\u043e\u0431\u043b\u0435\u043c\u0435: ') + $d.(U '\u041c\u043e\u0434\u0435\u043b\u044c')) } }
    }
    $vols = @(Get-CimSafe Win32_LogicalDisk -Filter 'DriveType=3')
    $volHtml = ''
    foreach ($v in $vols) {
        if (-not $v.Size) { continue }
        $usedPct = [int][math]::Round(100 * ($v.Size - $v.FreeSpace) / $v.Size)
        $freePct = 100 - $usedPct
        $cls = if ($freePct -lt $thrBad) { 'bad' } elseif ($freePct -lt $thrWarn) { 'warn' } else { 'ok' }
        $lbl = (Enc $v.DeviceID) + $(if ($v.VolumeName) { ' &middot; ' + (Enc $v.VolumeName) } else { '' })
        $volHtml += '<div class="vol"><div class="vol-h"><b>' + $lbl + '</b><span>' + (Enc $v.FileSystem) + ' &middot; ' + (U '\u0441\u0432\u043e\u0431\u043e\u0434\u043d\u043e ') + [math]::Round($v.FreeSpace / 1GB) + ' / ' + [math]::Round($v.Size / 1GB) + ' ' + (U '\u0413\u0411') + '</span></div><div class="bar"><i class="' + $cls + '" style="width:' + $usedPct + '%"></i></div></div>'
        if ($v.DeviceID -eq $env:SystemDrive) { [void]$checks.Add((Get-SysDiskCheck $v)) }
    }
    $gpu = Get-CimSafe Win32_VideoController | Where-Object { $_.Name -notmatch 'Parsec|Virtual|Remote|Mirror|Basic' } | Select-Object @{n = (U '\u0412\u0438\u0434\u0435\u043e\u0430\u0434\u0430\u043f\u0442\u0435\u0440'); e = { $_.Name } }, @{n = (U '\u0414\u0440\u0430\u0439\u0432\u0435\u0440'); e = { $_.DriverVersion } }
    $net = Get-CimSafe Win32_NetworkAdapterConfiguration -Filter 'IPEnabled=true' | Select-Object @{n = (U '\u0410\u0434\u0430\u043f\u0442\u0435\u0440'); e = { $_.Description } }, @{n = 'MAC'; e = { $_.MACAddress } }, @{n = 'IP'; e = { $_.IPAddress -join ', ' } }, @{n = (U '\u0428\u043b\u044e\u0437'); e = { $_.DefaultIPGateway -join ', ' } }
    $bat = Get-CimSafe Win32_Battery -ErrorAction SilentlyContinue | Select-Object @{n = (U '\u0411\u0430\u0442\u0430\u0440\u0435\u044f'); e = { $_.Name } }, @{n = (U '\u0417\u0430\u0440\u044f\u0434, %'); e = { $_.EstimatedChargeRemaining } }

    # ---- checks (src\Checks.ps1: thresholds come from config.json "checks") ----
    foreach ($c in @(Get-QuickChecks $os $up $ramTotal)) { if ($c) { [void]$checks.Add($c) } }
    $nOk = @($checks | Where-Object L -eq 'ok').Count; $nWarn = @($checks | Where-Object L -eq 'warn').Count; $nBad = @($checks | Where-Object L -eq 'bad').Count
    $checkHtml = (Get-CheckLead $checks) + (ConvertTo-CheckHtml $checks)

    # ---- software (from uninstall entries, system components and updates hidden) ----
    $sw = @(Get-Uninstall | Where-Object { $_.SystemComponent -ne 1 -and -not $_.ParentKeyName } |
        Sort-Object DisplayName | Select-Object -Property @{n = (U '\u041f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u0430'); e = { $_.DisplayName } }, @{n = (U '\u0412\u0435\u0440\u0441\u0438\u044f'); e = { $_.DisplayVersion } }, @{n = (U '\u0418\u0437\u0434\u0430\u0442\u0435\u043b\u044c'); e = { $_.Publisher } } -Unique)

    # ---- changes since the previous report of this PC ----
    $oldSnap = Read-Snapshot
    $curSnap = New-Snapshot $os $ramTotal $vols $dsk $sw
    $chgHtml = Get-ChangesHtml $oldSnap $curSnap

    # ---- page ----
    $general = [ordered]@{}
    $general[(U '\u041a\u043e\u043c\u043f\u044c\u044e\u0442\u0435\u0440')] = $env:COMPUTERNAME; $general[(U '\u041f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044c')] = $cs.Manufacturer; $general[(U '\u041c\u043e\u0434\u0435\u043b\u044c')] = $cs.Model
    $general[(U '\u0421\u0435\u0440\u0438\u0439\u043d\u044b\u0439 \u043d\u043e\u043c\u0435\u0440')] = $bios.SerialNumber; $general[(U '\u0421\u0438\u0441\u0442\u0435\u043c\u043d\u0430\u044f \u043f\u043b\u0430\u0442\u0430')] = "$($bb.Manufacturer) $($bb.Product)"; $general['BIOS'] = $bios.SMBIOSBIOSVersion
    $general[(U '\u041e\u043f\u0435\u0440\u0430\u0446\u0438\u043e\u043d\u043d\u0430\u044f \u0441\u0438\u0441\u0442\u0435\u043c\u0430')] = "$($os.Caption) ($($os.OSArchitecture)), build $($os.BuildNumber)"; $general[(U '\u0423\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u0430')] = $os.InstallDate.ToString('yyyy-MM-dd')
    $general[(U '\u0412\u0440\u0435\u043c\u044f \u0440\u0430\u0431\u043e\u0442\u044b')] = ('{0} {1} {2} {3}' -f $up.Days, (U '\u0434'), $up.Hours, (U '\u0447')); $general[(U '\u0414\u043e\u043c\u0435\u043d / \u0440\u0430\u0431\u043e\u0447\u0430\u044f \u0433\u0440\u0443\u043f\u043f\u0430')] = $cs.Domain; $general[(U '\u041f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u0435\u043b\u044c')] = $cs.UserName
    $sysVol = $vols | Where-Object { $_.DeviceID -eq $env:SystemDrive } | Select-Object -First 1
    $sysFree = if ($sysVol -and $sysVol.Size) { [string][math]::Round($sysVol.FreeSpace / 1GB) + ' ' + (U '\u0413\u0411 \u0441\u0432\u043e\u0431\u043e\u0434\u043d\u043e') } else { '-' }
    $chips = '<span class="chip">' + (Enc $cpuName) + '</span><span class="chip">' + $ramTotal + ' ' + (U '\u0413\u0411 \u041e\u0417\u0423') + '</span><span class="chip">' + (Enc $sysFree) + '</span><span class="chip">' + (Enc $os.Caption) + '</span>'
    $summary = "$env:COMPUTERNAME | $($cs.Manufacturer) $($cs.Model) | $cpuName | $ramTotal GB RAM | $($os.Caption)"
    $stat = '<div class="stats"><div class="st ok"><b>' + $nOk + '</b><span>' + (U '\u0432 \u043d\u043e\u0440\u043c\u0435') + '</span></div><div class="st warn"><b>' + $nWarn + '</b><span>' + (U '\u0432\u043d\u0438\u043c\u0430\u043d\u0438\u0435') + '</span></div><div class="st bad"><b>' + $nBad + '</b><span>' + (U '\u043f\u0440\u043e\u0431\u043b\u0435\u043c\u044b') + '</span></div></div>'

    $body  = (Card (U '\u0411\u044b\u0441\u0442\u0440\u0430\u044f \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430') 'pulse' ($stat + $checkHtml) 'wide')
    $body += (Card (U '\u0427\u0442\u043e \u0438\u0437\u043c\u0435\u043d\u0438\u043b\u043e\u0441\u044c \u0441 \u043f\u0440\u043e\u0448\u043b\u043e\u0433\u043e \u0440\u0430\u0437\u0430') 'info' $chgHtml 'wide')
    $body += (Card (U '\u0421\u0438\u0441\u0442\u0435\u043c\u0430') 'info' (KvList $general))
    $body += (Card (U '\u041f\u0440\u043e\u0446\u0435\u0441\u0441\u043e\u0440') 'cpu' (HtmlTbl $cpu))
    $body += (Card ((U '\u041e\u043f\u0435\u0440\u0430\u0442\u0438\u0432\u043d\u0430\u044f \u043f\u0430\u043c\u044f\u0442\u044c') + " ($ramTotal " + (U '\u0413\u0411') + ')') 'ram' (HtmlTbl $ram))
    $body += (Card (U '\u041d\u0430\u043a\u043e\u043f\u0438\u0442\u0435\u043b\u0438 \u0438 \u0442\u043e\u043c\u0430') 'disk' ((HtmlTbl $dsk) + '<div class="vols">' + $volHtml + '</div>') 'wide')
    $body += (Card (U '\u0412\u0438\u0434\u0435\u043e\u0430\u0434\u0430\u043f\u0442\u0435\u0440') 'gpu' (HtmlTbl $gpu))
    $body += (Card (U '\u0421\u0435\u0442\u044c') 'net' (HtmlTbl $net))
    if ($bat) { $body += (Card (U '\u0411\u0430\u0442\u0430\u0440\u0435\u044f') 'pulse' (HtmlTbl $bat)) }
    $body += (Card ((U '\u0423\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u043d\u044b\u0435 \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u044b') + " ($($sw.Count))") 'apps' ('<input id="q" class="search" type="search" aria-label="' + (U '\u041f\u043e\u0438\u0441\u043a \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u044b') + '" placeholder="' + (U '\u041f\u043e\u0438\u0441\u043a \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u044b...') + '">' + '<div id="qc" class="muted" aria-live="polite"></div>' + (HtmlTbl $sw 'sw')) 'wide long')

    $tpl = U @'
<!DOCTYPE html>
<html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>{{PC}} - InspektorOfficEr</title>
<style>
:root{--bg:#f4f6fb;--card:#fff;--ink:#14182b;--mut:#6b7390;--line:#e4e8f2;--acc:#4f46e5;--acc2:#06b6d4;--ok:#16a34a;--warn:#d97706;--bad:#dc2626;--sh:0 1px 2px rgba(20,24,43,.05),0 8px 24px rgba(20,24,43,.06);color-scheme:light}
:root[data-theme=dark]{--bg:#0b0e1a;--card:#131830;--ink:#e8ebf7;--mut:#8b93b5;--line:#232a4a;--sh:0 1px 2px rgba(0,0,0,.4),0 8px 28px rgba(0,0,0,.35);color-scheme:dark}
@media(prefers-color-scheme:dark){:root:not([data-theme=light]){--bg:#0b0e1a;--card:#131830;--ink:#e8ebf7;--mut:#8b93b5;--line:#232a4a;--sh:0 1px 2px rgba(0,0,0,.4),0 8px 28px rgba(0,0,0,.35);color-scheme:dark}}
*{box-sizing:border-box}html,body{margin:0}body{background:var(--bg);color:var(--ink);font:14px/1.5 "Segoe UI Variable","Segoe UI",system-ui,Arial,sans-serif;-webkit-font-smoothing:antialiased}
.wrap{max-width:1180px;margin:0 auto;padding:0 20px 40px}
.top{display:flex;align-items:center;justify-content:space-between;padding:18px 0}
.brand{display:flex;align-items:center;gap:10px;font-weight:700;letter-spacing:.2px}.brand svg{width:34px;height:34px}.brand small{display:block;font-weight:500;color:var(--mut);font-size:11px;letter-spacing:.4px}
.btns{display:flex;gap:8px}.btn{appearance:none;border:1px solid var(--line);background:var(--card);color:var(--ink);padding:7px 12px;border-radius:10px;font:inherit;cursor:pointer;box-shadow:var(--sh)}.btn:hover{border-color:var(--acc)}
.hero{position:relative;overflow:hidden;border-radius:22px;padding:30px 30px 26px;color:#fff;background:linear-gradient(135deg,#4f46e5 0%,#7c3aed 48%,#06b6d4 100%);box-shadow:0 18px 50px rgba(79,70,229,.35)}
.hero:after{content:"";position:absolute;right:-60px;top:-60px;width:260px;height:260px;border-radius:50%;background:rgba(255,255,255,.12)}
.hero h1{margin:0 0 4px;font-size:34px;letter-spacing:.3px}.hero p{margin:0;opacity:.9}.chips{margin-top:16px;display:flex;flex-wrap:wrap;gap:8px;position:relative;z-index:1}
.chip{background:rgba(255,255,255,.18);backdrop-filter:blur(6px);border:1px solid rgba(255,255,255,.28);padding:5px 12px;border-radius:999px;font-size:12.5px}
.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin-top:18px}
.card{background:var(--card);border:1px solid var(--line);border-radius:18px;padding:18px 20px;box-shadow:var(--sh);min-width:0}.card.wide{grid-column:1/-1}
.card h2{display:flex;align-items:center;gap:10px;margin:0 0 12px;font-size:15px}.ic{width:20px;height:20px;color:var(--acc)}
.kv{margin:0;display:grid;grid-template-columns:1fr 1fr;gap:4px 18px}.kv div{display:flex;flex-direction:column;padding:6px 0;border-bottom:1px dashed var(--line)}.kv dt{font-size:11.5px;color:var(--mut);text-transform:uppercase;letter-spacing:.4px}.kv dd{margin:0;word-break:break-word}
.scroll{overflow-x:auto}.tbl{width:100%;border-collapse:collapse}.tbl th{position:sticky;top:0;text-align:left;font-size:11.5px;color:var(--mut);text-transform:uppercase;letter-spacing:.4px;padding:8px 10px;border-bottom:1px solid var(--line);background:var(--card)}.tbl td{padding:8px 10px;border-bottom:1px solid var(--line)}.tbl tr:hover td{background:rgba(79,70,229,.06)}
.muted{color:var(--mut)}
.stats{display:flex;gap:12px;margin-bottom:12px;flex-wrap:wrap}.st{flex:1;min-width:110px;border-radius:14px;padding:10px 14px;border:1px solid var(--line)}.st b{font-size:26px;display:block;line-height:1.1}.st span{color:var(--mut);font-size:12px}
.st.ok b{color:var(--ok)}.st.warn b{color:var(--warn)}.st.bad b{color:var(--bad)}
.checks{list-style:none;margin:0;padding:0}.checks li{display:flex;align-items:center;gap:10px;padding:8px 0;border-bottom:1px solid var(--line)}.checks li:last-child{border:0}
.checks i{width:10px;height:10px;border-radius:50%;flex:none;background:var(--ok);box-shadow:0 0 0 4px rgba(22,163,74,.15)}.checks .warn i{background:var(--warn);box-shadow:0 0 0 4px rgba(217,119,6,.18)}.checks .bad i{background:var(--bad);box-shadow:0 0 0 4px rgba(220,38,38,.18)}
.vols{margin-top:14px;display:grid;gap:12px}.vol-h{display:flex;justify-content:space-between;gap:10px;margin-bottom:5px;flex-wrap:wrap}.vol-h span{color:var(--mut)}
.bar{height:10px;border-radius:99px;background:var(--line);overflow:hidden}.bar i{display:block;height:100%;border-radius:99px;background:var(--ok)}.bar i.warn{background:var(--warn)}.bar i.bad{background:var(--bad)}
.search{width:100%;margin-bottom:10px;padding:10px 14px;border-radius:12px;border:1px solid var(--line);background:var(--bg);color:var(--ink);font:inherit}.search:focus{outline:2px solid var(--acc);border-color:transparent}
#sw tbody tr.hide{display:none}
.foot{margin-top:26px;text-align:center;color:var(--mut);font-size:12px}.foot b{color:var(--ink)}
@media(max-width:820px){.grid{grid-template-columns:1fr}.kv{grid-template-columns:1fr}.hero h1{font-size:26px}}
@media print{body{background:#fff}.btns{display:none}.hero{box-shadow:none;-webkit-print-color-adjust:exact;print-color-adjust:exact}.card{box-shadow:none;break-inside:avoid}}

.lead{margin:0 0 12px;padding:10px 14px;border-radius:12px;border:1px solid var(--line);border-left-width:5px;font-weight:600}.lead.bad{border-color:var(--bad)}.lead.warn{border-color:var(--warn)}.lead.ok{border-color:var(--ok)}
.checks li{align-items:flex-start}.checks i{margin-top:6px}.lv{flex:none;min-width:78px;font-size:11.5px;font-weight:700;text-transform:uppercase;letter-spacing:.3px;padding-top:2px}.tx{min-width:0;overflow-wrap:anywhere}.act{display:block;color:var(--mut);margin-top:2px}
.chg{margin:0;padding:0;list-style:none}.chg li{padding:7px 0;border-bottom:1px solid var(--line);overflow-wrap:anywhere}.chg li:last-child{border:0}.chg b{margin-right:6px}
.btn:focus-visible,.search:focus-visible,a:focus-visible{outline:2px solid var(--acc);outline-offset:2px}
#sw tr[hidden]{display:none}
@media print{.search,#qc{display:none}.card.long{break-inside:auto}.tbl thead{display:table-header-group}.tbl tr{break-inside:avoid}}
</style></head><body><main class="wrap">
<div class="top"><div class="brand"><svg viewBox="0 0 48 48"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#4f46e5"/><stop offset="1" stop-color="#06b6d4"/></linearGradient></defs><rect width="48" height="48" rx="12" fill="url(#g)"/><rect x="9" y="11" width="24" height="17" rx="3" fill="none" stroke="#fff" stroke-width="2.6"/><path d="M15 33h12" stroke="#fff" stroke-width="2.6" stroke-linecap="round"/><circle cx="32" cy="30" r="7" fill="#fff" fill-opacity=".18" stroke="#fff" stroke-width="2.6"/><path d="M37 35l5 5" stroke="#fff" stroke-width="3" stroke-linecap="round"/></svg><div>InspektorOfficEr<small>PC INSPECTION REPORT</small></div></div>
<div class="btns"><button class="btn" id="cp" data-s="{{SUMMARY}}">{{B_COPY}}</button><button class="btn" id="th">{{B_THEME}}</button><button class="btn" onclick="window.print()">{{B_PRINT}}</button></div></div>
<div class="hero"><h1>{{PC}}</h1><p>{{SUB}}</p><div class="chips">{{CHIPS}}</div></div>
<div class="grid">{{BODY}}</div>
<div class="foot">{{GENERATED}} {{DATE}} &middot; <b>InspektorOfficEr</b> v{{VER}}</div>
</main>
<script>
(function(){var r=document.documentElement;try{var t=localStorage.getItem("ioe-theme");if(t)r.setAttribute("data-theme",t)}catch(e){}
document.getElementById("th").onclick=function(){var d=r.getAttribute("data-theme");if(!d)d=window.matchMedia("(prefers-color-scheme:dark)").matches?"dark":"light";var n=d==="dark"?"light":"dark";r.setAttribute("data-theme",n);try{localStorage.setItem("ioe-theme",n)}catch(e){}};
var q=document.getElementById("q");if(q){var rows=[].slice.call(document.querySelectorAll("#sw tbody tr")),idx=rows.map(function(tr){return tr.textContent.toLowerCase()}),tm=0,qc=document.getElementById("qc");q.oninput=function(){clearTimeout(tm);tm=setTimeout(function(){var v=q.value.toLowerCase().trim(),n=0;rows.forEach(function(tr,i){var h=v!==""&&idx[i].indexOf(v)<0;if(h!==tr.hidden)tr.hidden=h;if(!h)n++});if(qc)qc.textContent=v?n+" / "+rows.length:""},120)}}
var c=document.getElementById("cp");c.onclick=function(){var s=c.getAttribute("data-s"),o=c.textContent;function ok(){c.textContent="OK";setTimeout(function(){c.textContent=o},1200)}
if(navigator.clipboard){navigator.clipboard.writeText(s).then(ok,ok)}else{var a=document.createElement("textarea");a.value=s;document.body.appendChild(a);a.select();try{document.execCommand("copy")}catch(e){}document.body.removeChild(a);ok()}};})();
</script></body></html>
'@
    $doc = $tpl.Replace('{{PC}}', (Enc $env:COMPUTERNAME)).Replace('{{SUB}}', (Enc "$($cs.Manufacturer) $($cs.Model)")).Replace('{{CHIPS}}', $chips).Replace('{{BODY}}', $body).Replace('{{SUMMARY}}', (Enc $summary)).Replace('{{DATE}}', (Get-Date -Format 'yyyy-MM-dd HH:mm')).Replace('{{VER}}', $AppVer).Replace('{{GENERATED}}', (U '\u041e\u0442\u0447\u0451\u0442 \u0441\u043e\u0437\u0434\u0430\u043d')).Replace('{{B_COPY}}', (U '\u041a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0441\u0432\u043e\u0434\u043a\u0443')).Replace('{{B_THEME}}', (U '\u0422\u0435\u043c\u0430')).Replace('{{B_PRINT}}', (U '\u041f\u0435\u0447\u0430\u0442\u044c'))
    [IO.File]::WriteAllText($path, $doc, (New-Object Text.UTF8Encoding($true)))
    Save-Snapshot $curSnap      # only after the report exists: the next report compares against this one
}

# ===================== INVENTORY: data collectors =====================
function Tm($name, [scriptblock]$b) {
    $sw = [Diagnostics.Stopwatch]::StartNew()
    try { $r = & $b }
    catch { Write-Log ERROR "$name collector failed: $($_.Exception.Message)"; $r = $NO }    # one broken collector must not stop the inventory
    Write-Host ('  ({0}: {1:N1}s)' -f $name, $sw.Elapsed.TotalSeconds) -ForegroundColor DarkGray
    $r
}

function Get-UserProfileDirs {
    $r = @()
    try { $r += (Get-ChildItem 'C:\Users' -Directory -Force -ErrorAction SilentlyContinue | ForEach-Object { $_.FullName }) } catch { Write-Log DEBUG "profiles: cannot list C:\Users: $($_.Exception.Message)" }
    $r += 'C:\Windows\ServiceProfiles\LocalService', 'C:\Windows\ServiceProfiles\NetworkService', 'C:\Windows\System32\config\systemprofile'
    $r | Where-Object { $_ -and (Test-Path $_) } | Select-Object -Unique
}

# shared read (works even if the app keeps the file open), BOM / UTF-8 / cp1251 aware
function Read-TextSmart($path) {
    $fs = [IO.File]::Open($path, 'Open', 'Read', 'ReadWrite,Delete')
    try { $ms = New-Object IO.MemoryStream; $fs.CopyTo($ms); $b = $ms.ToArray() } finally { $fs.Dispose() }
    if ($b.Length -ge 2 -and $b[0] -eq 0xFF -and $b[1] -eq 0xFE) { return [Text.Encoding]::Unicode.GetString($b).TrimStart([char]0xFEFF) }
    if ($b.Length -ge 2 -and $b[0] -eq 0xFE -and $b[1] -eq 0xFF) { return [Text.Encoding]::BigEndianUnicode.GetString($b).TrimStart([char]0xFEFF) }
    $t = [Text.Encoding]::UTF8.GetString($b)
    if ($t.Contains([string][char]0xFFFD)) { $t = [Text.Encoding]::GetEncoding(1251).GetString($b) }
    $t.TrimStart([char]0xFEFF)
}

function Get-Uninstall {
    if ($script:UninstallCache) { return $script:UninstallCache }
    $k = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*', 'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*', 'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*'
    $script:UninstallCache = @(Get-ItemProperty $k -ErrorAction SilentlyContinue | Where-Object { $_.DisplayName })
    $script:UninstallCache
}

# ---- compatibility signatures ----
# The ONLY place with product-specific technical identifiers (folder / file / service / process names, CLI switch).
# They are used read-only to recognise software that is ALREADY installed on the audited PC. No third-party code is bundled,
# distributed or modified. Product names and trademarks belong to their respective owners; no affiliation or endorsement is implied.
$script:Sig = @{
    RemoteA = @{ Folder = 'AnyDesk';   ConfFile = 'system.conf'; ExeName = 'AnyDesk.exe';   ProcPat = '^AnyDesk';   CliArgs = '--get-id'
                 IdRx = '(?m)^\s*ad\.(?:anynet|anydesk)\.id\s*=\s*(\d+)' }
    RemoteB = @{ Folder = 'HopToDesk'; ConfFile = 'HopToDesk.toml'; ExeName = 'HopToDesk.exe'; ProcPat = '^HopToDesk'; CliArgs = '--get-id'
                 IdRx = '(?m)^\s*id\s*=\s*[''"]([A-Za-z0-9]+)[''"]' }
    DiskExclude = 'MiniTool|ShadowMaker|ShadowCopy|Volume Shadow|SDRSVC|SDXHelper'
    Disk = [ordered]@{
        'Disk protection (type A)' = @{ Pat = 'Deep ?Freeze|DFServ|DF5Serv|DepFrz|DeepFrz|FrzState2k|DFRTSvc|Persi0'
                                        Paths = @('C:\Persi0', 'C:\Program Files\Faronics\Deep Freeze*', 'C:\Program Files (x86)\Faronics\Deep Freeze*',
                                                  (Join-Path $env:windir 'SysWOW64\DFServ.exe'), (Join-Path $env:windir 'System32\DFServ.exe'),
                                                  (Join-Path $env:windir 'System32\drivers\DepFrz.sys')) }
        'Disk protection (type B)' = @{ Pat = 'Shadow ?Defender|ShadowDefender|SDCoreService|SDDrv'
                                        Paths = @('C:\Program Files\Shadow Defender', 'C:\Program Files (x86)\Shadow Defender') }
    }
}

# ---- is the program present at all? (tells "not installed" from "installed, but its ID was not found") ----
function Test-AppPresent([string]$pat) {
    $why = @()
    try { $x = Get-Process -ErrorAction SilentlyContinue | Where-Object { $_.Name -match $pat } | Select-Object -First 1; if ($x) { $why += "process: $($x.Name)" } } catch { }
    try { $x = Get-ChildItem 'HKLM:\SYSTEM\CurrentControlSet\Services' -ErrorAction SilentlyContinue | Where-Object { $_.PSChildName -match $pat } | Select-Object -First 1; if ($x) { $why += "service: $($x.PSChildName)" } } catch { }
    try { $x = Get-Uninstall | Where-Object { $_.DisplayName -match $pat } | Select-Object -First 1; if ($x) { $why += "installed: $($x.DisplayName)" } } catch { }
    $why
}

# executables of a program: Seen = anywhere (running copy, portable), Installed = Program Files / uninstall entry / config.json (safe to call with a CLI switch)
function Get-AppExePaths([string]$procPat, [string]$uninstPat, [string[]]$known, [string]$exeName, [string]$cfgKey) {
    $seen = New-Object Collections.ArrayList; $inst = New-Object Collections.ArrayList
    try { foreach ($p in @(Get-Process -ErrorAction SilentlyContinue | Where-Object { $_.Name -match $procPat })) { try { if ($p.Path) { [void]$seen.Add([string]$p.Path) } } catch { } } } catch { }
    foreach ($k in $known) { if ($k) { [void]$inst.Add($k) } }
    try { foreach ($u in @(Get-Uninstall | Where-Object { $_.DisplayName -match $uninstPat })) { if ($u.InstallLocation) { [void]$inst.Add((Join-Path ([string]$u.InstallLocation).Trim('"') $exeName)) } } } catch { }
    foreach ($x in @(Cfg $cfgKey @())) { if ($x) { [void]$inst.Add([string]$x) } }
    $ok = { param($l) @($l | Where-Object { $_ -and (Test-Path -LiteralPath $_ -PathType Leaf) } | Select-Object -Unique) }
    [pscustomobject]@{ Installed = (& $ok $inst); Seen = (& $ok (@($inst) + @($seen))) }
}

function Get-ProgramFilesPaths([string]$rel) {
    $r = @()
    foreach ($b in @($env:ProgramFiles, ${env:ProgramFiles(x86)})) { if ($b) { $r += (Join-Path $b $rel) } }
    if ($env:LOCALAPPDATA) { $r += (Join-Path $env:LOCALAPPDATA ('Programs\' + $rel)) }
    $r
}

# ---- remote access tool A: plain-text ID setting in the program's config folder; portable copies keep it in %APPDATA% too ----
function Get-RemoteIdA {
    $A = $script:Sig.RemoteA
    $files = @()
    if ($env:ProgramData) { $files += Join-Path $env:ProgramData ($A.Folder + '\' + $A.ConfFile) }
    if ($env:APPDATA)     { $files += Join-Path $env:APPDATA ($A.Folder + '\' + $A.ConfFile) }
    foreach ($d in (Get-UserProfileDirs)) { $files += Join-Path $d ('AppData\Roaming\' + $A.Folder + '\' + $A.ConfFile) }
    foreach ($d in @(Cfg 'remoteAccessDetect.extraConfigDirsA' @())) { if ($d) { $files += Join-Path ([string]$d) $A.ConfFile } }     # config.json: non-standard config folders
    foreach ($f in ($files | Select-Object -Unique)) {
        if (-not (Test-Path -LiteralPath $f)) { Write-Log DEBUG "remote A: no file $f"; continue }
        try {
            $m = [regex]::Match((Read-TextSmart $f), $A.IdRx)
            if ($m.Success) { $script:Src.RemoteA = $f; Write-Log DEBUG "remote A: id found in $f"; return $m.Groups[1].Value }
            Write-Log DEBUG "remote A: $f exists, but has no ID line"
        } catch { Write-Log DEBUG "remote A: cannot read ${f}: $($_.Exception.Message)" }
    }
    # no config: ask an INSTALLED copy through its command-line switch (can be turned off: features.remoteAccessCli / -NoRemoteCli)
    if (-not $NoRemoteCli) {
        $ex = Get-AppExePaths $A.Folder $A.ProcPat @(Get-ProgramFilesPaths ($A.Folder + '\' + $A.ExeName)) $A.ExeName 'remoteAccessDetect.extraPathsA'
        foreach ($exe in @($ex.Installed | Select-Object -First 2)) {
            $x = Invoke-External $exe $A.CliArgs ([int](Cfg 'timeouts.remoteCliSec' 8))
            Write-Log DEBUG "remote A: cli $exe $($A.CliArgs) exit=$($x.ExitCode) timeout=$($x.TimedOut) error=$($x.Error)"
            $m = [regex]::Match($x.Stdout, '(?m)^\s*(\d{6,})\s*$')
            if ($m.Success) { $script:Src.RemoteA = "$exe $($A.CliArgs) (CLI)"; return $m.Groups[1].Value }
        }
    }
    $why = @(Test-AppPresent $A.ProcPat)
    try {   # portable copy lying around (desktop / downloads), not running
        foreach ($d in (Get-UserProfileDirs)) { foreach ($sub in 'Desktop', 'Downloads') {
            $x = Get-ChildItem (Join-Path $d $sub) -Filter ($A.Folder + '*.exe') -File -ErrorAction SilentlyContinue | Select-Object -First 1
            if ($x) { $why += "portable exe: $($x.FullName)" }
        } }
    } catch { }
    if ($why.Count) {
        $script:Src.RemoteA = 'present, but no ID found: ' + ($why -join ' ; ')
        Write-Log WARN 'Remote access tool A is present, but its ID was not found (start it once, or add its config folder to config.json: remoteAccessDetect.extraConfigDirsA)'
        return $NoId
    }
    Write-Log DEBUG 'remote A: not installed, ID not found in any known location'
    return $NO
}

# ---- remote access tool B: ID in a *.toml settings file (or through the installed program's CLI) ----
function Find-RemoteIdB($dir) {
    $B = $script:Sig.RemoteB
    $tomls = @(Get-ChildItem $dir -Recurse -Depth 3 -Filter '*.toml' -File -Force -ErrorAction SilentlyContinue |
               Sort-Object @{ e = { if ($_.Name -ieq $B.ConfFile) { 0 } else { 1 } } }, Name)
    foreach ($f in $tomls) {
        try {
            $m = [regex]::Match((Read-TextSmart $f.FullName), $B.IdRx)
            if ($m.Success) { return [pscustomobject]@{ Id = $m.Groups[1].Value; File = $f.FullName } }
        } catch { Write-Log DEBUG "remote B: cannot read $($f.FullName): $($_.Exception.Message)" }
    }
    $null
}

function Get-RemoteIdB {
    $B = $script:Sig.RemoteB
    $log = New-Object Collections.ArrayList
    $note = { param($m) [void]$log.Add($m); Write-Log DEBUG "remote B: $m" }
    $dirs = @()
    if (-not $NoRemoteCli) {   # some builds keep no plain ID in *.toml: ask the installed program itself
        $ex = Get-AppExePaths $B.Folder $B.ProcPat @(Get-ProgramFilesPaths ($B.Folder + '\' + $B.ExeName)) $B.ExeName 'remoteAccessDetect.extraPathsB'
        if ($ex.Installed.Count) {
            $to = [int](Cfg 'timeouts.remoteCliSec' 8)
            foreach ($exe in @($ex.Installed | Select-Object -First 2)) {
                $x = Invoke-External $exe $B.CliArgs $to
                & $note "cli $exe $($B.CliArgs) exit=$($x.ExitCode) timeout=$($x.TimedOut) error=$($x.Error)"
                $m = [regex]::Match($x.Stdout, '(?m)^\s*(\d{6,})\s*$')
                if ($m.Success) { $script:Src.RemoteB = "$exe $($B.CliArgs) (CLI)"; return $m.Groups[1].Value }
                & $note 'cli returned no numeric ID'
            }
        } else { & $note 'executable not found (Program Files, per-user install, uninstall entries, config.json)' }
    }

    if ($env:APPDATA)     { $dirs += Join-Path $env:APPDATA $B.Folder }
    if ($env:ProgramData) { $dirs += Join-Path $env:ProgramData $B.Folder }
    foreach ($d in (Get-UserProfileDirs)) { $dirs += Join-Path $d ('AppData\Roaming\' + $B.Folder); $dirs += Join-Path $d ('AppData\Local\' + $B.Folder) }
    foreach ($d in ($dirs | Select-Object -Unique)) {
        $ex2 = Test-Path $d; & $note "dir $d exists=$ex2"
        if (-not $ex2) { continue }
        $r = Find-RemoteIdB $d
        if ($r) { $script:Src.RemoteB = $r.File; return $r.Id }
        & $note '   no id in *.toml'
    }

    # service profiles are ACL-protected: copy *.toml with backup privilege (robocopy /B), then parse the copy.
    # /B needs an elevated session, without it robocopy only fails, so it is skipped.
    if (Test-IsAdmin) {
        $tmpRoot = Join-Path $env:TEMP ('ra_' + [guid]::NewGuid().ToString('N').Substring(0, 8))
        $rto = [int](Cfg 'timeouts.robocopySec' 30)
        try {
            foreach ($s in 'C:\Windows\ServiceProfiles\LocalService', 'C:\Windows\ServiceProfiles\NetworkService', 'C:\Windows\System32\config\systemprofile') {
                $src = Join-Path $s ('AppData\Roaming\' + $B.Folder)
                $dst = Join-Path $tmpRoot (Split-Path $s -Leaf)
                try {
                    $x = Invoke-External 'robocopy' ('"{0}" "{1}" *.toml /E /B /R:0 /W:0 /NP /NJH /NJS /NFL /NDL' -f $src, $dst) $rto
                    & $note "robocopy /B $src exit=$($x.ExitCode) timeout=$($x.TimedOut) $($x.Error)"
                    if (Test-Path $dst) {
                        $r = Find-RemoteIdB $dst
                        if ($r) { $script:Src.RemoteB = $r.File.Replace($dst, $src) + ' (backup-mode copy)'; return $r.Id }
                        & $note '   copied, but no id in *.toml'
                    }
                } catch { & $note "robocopy error: $($_.Exception.Message)" }
            }
        } finally { Remove-Item $tmpRoot -Recurse -Force -ErrorAction SilentlyContinue }
    } else { & $note 'not elevated: service profiles (robocopy /B) skipped' }

    $why = @(Test-AppPresent $B.ProcPat)
    if ($why.Count) {
        $script:Src.RemoteB = 'present, but no ID found: ' + ($why -join ' ; ')
        Write-Host '  Remote access tool B is present, but its ID was not found; search log: Raports\_remote_search.txt' -ForegroundColor Yellow
        foreach ($w in $why) { [void]$log.Add($w) }
        try { $log | Out-File (Join-Path $OutDir '_remote_search.txt') -Encoding utf8 } catch { }
        return $NoId
    }
    return $NO
}

# ---- disk protection software: services, processes, drivers (all in the Services registry key), uninstall entries, known folders ----
# Presence is detected; the protected / unprotected state cannot be read reliably, so it is not claimed.
function Get-DiskProtectionStatus {
    $on   = [string](Cfg 'diskProtectionDetect.enabledText' (U '\u0412\u043a\u043b\u044e\u0447\u0435\u043d\u043e'))
    $excl = [string]$script:Sig.DiskExclude     # look-alikes that are NOT disk protection
    $defs = [ordered]@{}
    foreach ($k in $script:Sig.Disk.Keys) { $defs[$k] = $script:Sig.Disk[$k] }
    foreach ($d in @(Cfg 'diskProtectionDetect.disableBuiltin' @())) { $defs.Remove([string]$d) }       # config.json: drop a built-in entry
    foreach ($xp in @(Cfg 'diskProtectionDetect.extraProducts' @())) {                                  # config.json: add your own entry
        if ($xp.name -and $xp.pattern) { $defs[[string]$xp.name] = @{ Pat = [string]$xp.pattern; Paths = @($xp.paths | Where-Object { $_ }) } }
    }
    $ex2 = [string](Cfg 'diskProtectionDetect.excludePattern' ''); if ($ex2) { $excl = "$excl|$ex2" }
    $procs = @(); try { $procs = @(Get-Process -ErrorAction SilentlyContinue | ForEach-Object { $_.Name }) } catch { Write-Log DEBUG "disk protection: Get-Process failed: $($_.Exception.Message)" }
    $svcs  = @(); try { $svcs = @(Get-ChildItem 'HKLM:\SYSTEM\CurrentControlSet\Services' -ErrorAction SilentlyContinue | ForEach-Object { "$($_.PSChildName) | $($_.GetValue('DisplayName')) | $($_.GetValue('ImagePath'))" }) } catch { Write-Log DEBUG "disk protection: cannot read the Services registry key: $($_.Exception.Message)" }
    $apps  = @(Get-Uninstall | ForEach-Object { "$($_.DisplayName) | $($_.Publisher)" })

    $res = @(); $why = @()
    try {                                               # native: Windows Unified Write Filter (Enterprise / Education / IoT editions)
        $f = Get-CimInstance -Namespace 'root\standardcimv2\embedded' -ClassName UWF_Filter -ErrorAction Stop | Select-Object -First 1
        if ($f -and $f.CurrentEnabled) { $res += "Windows UWF $([char]0x2014) $on"; $why += 'UWF_Filter.CurrentEnabled = True' }
    } catch { Write-Log DEBUG "disk protection: UWF is not available: $($_.Exception.Message)" }
    foreach ($prod in $defs.Keys) {
        $pat = $defs[$prod].Pat; $ev = @()
        $x = $procs | Where-Object { $_ -match $pat -and $_ -notmatch $excl } | Select-Object -First 1; if ($x) { $ev += "process: $x" }
        $x = $svcs  | Where-Object { $_ -match $pat -and $_ -notmatch $excl } | Select-Object -First 1; if ($x) { $ev += "service/driver: $x" }
        $x = $apps  | Where-Object { $_ -match $pat -and $_ -notmatch $excl } | Select-Object -First 1; if ($x) { $ev += "installed: $x" }
        foreach ($p in $defs[$prod].Paths) { if (Test-Path $p -ErrorAction SilentlyContinue) { $ev += "path: $p"; break } }
        if (-not $ev.Count) { Write-Log DEBUG "disk protection: $prod - no evidence (processes=$($procs.Count) services=$($svcs.Count) apps=$($apps.Count))"; continue }
        $res += "$prod $([char]0x2014) $on"
        $why += "$prod <- " + ($ev -join ' ; ')
        Write-Log DEBUG ("disk protection: $prod - " + ($ev -join ' ; '))
    }
    if ($res.Count) { $script:Src.Disk = ($why -join ' || '); return ($res -join '; ') }
    return $NO
}

# ===================== PC PASSPORT =====================
# ---- passport: C:\ -> script folder (USB) -> desktops (current user, all users, Public, OneDrive) ----
function Get-DesktopDirs {
    $r = @()
    try { $r += [Environment]::GetFolderPath('Desktop') } catch { }
    if ($env:USERPROFILE) { $r += Join-Path $env:USERPROFILE 'Desktop' }
    foreach ($d in @(Get-ChildItem 'C:\Users' -Directory -Force -ErrorAction SilentlyContinue)) {
        $r += Join-Path $d.FullName 'Desktop'
        foreach ($o in @(Get-ChildItem $d.FullName -Directory -Filter 'OneDrive*' -Force -ErrorAction SilentlyContinue)) { $r += Join-Path $o.FullName 'Desktop' }
    }
    $r += 'C:\Users\Public\Desktop'
    $r | Where-Object { $_ -and (Test-Path $_) } | Select-Object -Unique
}

function Read-PassportFile($path) {
    $al = @{
        Floor = @((U '\u042d\u0442\u0430\u0436'), 'Floor')
        Room  = @((U '\u041a\u0430\u0431\u0438\u043d\u0435\u0442'), (U '\u041f\u043e\u043c\u0435\u0449\u0435\u043d\u0438\u0435'), 'Room')
        Place = @((U '\u041c\u0435\u0441\u0442\u043e'), (U '\u0420\u0430\u0431\u043e\u0447\u0435\u0435 \u043c\u0435\u0441\u0442\u043e'), 'Place')
        User  = @((U '\u041f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u0435\u043b\u044c'), 'User')
    }
    $v = @{ Floor = ''; Room = ''; Place = ''; User = '' }
    $t = (Read-TextSmart $path).Trim()
    if ($t.StartsWith('{')) {
        $o = $t | ConvertFrom-Json
        foreach ($prop in $o.PSObject.Properties) {
            foreach ($f in @($al.Keys)) { if ($al[$f] -contains $prop.Name.Trim() -and $null -ne $prop.Value) { $v[$f] = ([string]$prop.Value).Trim() } }
        }
    } else {
        foreach ($line in ($t -split "`r?`n")) {
            $m = [regex]::Match($line, '^\s*([^:=]+?)\s*[:=]\s*(.*?)\s*$')
            if (-not $m.Success) { continue }
            foreach ($f in @($al.Keys)) { if ($al[$f] -contains $m.Groups[1].Value) { $v[$f] = $m.Groups[2].Value } }
        }
    }
    if (@($v.Values | Where-Object { $_ }).Count) { return $v }
    $null
}

# ---- no passport found: ask once, save on the USB drive (survives reboots of systems with disk protection) ----
function Ask-Passport {
    $maxRoom = @{}
    $cr = Cfg 'passport.roomsPerFloor' $null
    if ($cr) { foreach ($pr in $cr.PSObject.Properties) { $maxRoom[[string]$pr.Name] = [int]$pr.Value } }
    if (-not $maxRoom.Count) { $maxRoom = @{ '1' = 10; '2' = 10 } }     # default: rooms per floor
    Write-Host ''
    Write-Host ('  ' + (U '\u041f\u0430\u0441\u043f\u043e\u0440\u0442 \u041f\u041a \u043d\u0435 \u043d\u0430\u0439\u0434\u0435\u043d. \u0423\u043a\u0430\u0436\u0438\u0442\u0435 \u0440\u0430\u0441\u043f\u043e\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u043f\u043e \u043f\u043b\u0430\u043d\u0443 \u0437\u0434\u0430\u043d\u0438\u044f (Enter - \u043f\u0440\u043e\u043f\u0443\u0441\u0442\u0438\u0442\u044c).')) -ForegroundColor Yellow
    $x = 0
    while ($true) {
        $fl = (Read-Host ('  ' + ((U '\u042d\u0442\u0430\u0436') + ' (' + (($maxRoom.Keys | Sort-Object) -join ' / ') + ')'))).Trim()
        if ($fl -eq '') { return $null }
        if ($maxRoom.ContainsKey($fl)) { break }
    }
    while ($true) {
        $rm = (Read-Host ('  ' + ((U '\u041f\u043e\u043c\u0435\u0449\u0435\u043d\u0438\u0435 (\u043d\u043e\u043c\u0435\u0440 \u043f\u043e \u043f\u043b\u0430\u043d\u0443, 1-{0})') -f $maxRoom[$fl]))).Trim()
        if ($rm -eq '') { return $null }
        if ([int]::TryParse($rm, [ref]$x) -and $x -ge 1 -and $x -le $maxRoom[$fl]) { $rm = [string]$x; break }
    }
    while ($true) {
        $pl = (Read-Host ('  ' + (U '\u0420\u0430\u0431\u043e\u0447\u0435\u0435 \u043c\u0435\u0441\u0442\u043e (\u043d\u043e\u043c\u0435\u0440 \u0432 \u043f\u043e\u043c\u0435\u0449\u0435\u043d\u0438\u0438)'))).Trim()
        if ($pl -eq '') { return $null }
        if ([int]::TryParse($pl, [ref]$x) -and $x -ge 1) { $pl = [string]$x; break }
    }
    $us = (Read-Host ('  ' + (U '\u041f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u0435\u043b\u044c (Enter - \u043d\u0435 \u043c\u0435\u043d\u044f\u0442\u044c)'))).Trim()
    $r = @{ Floor = $fl; Room = $rm; Place = $pl; User = $us; Source = (U '\u0432\u0432\u0435\u0434\u0435\u043d\u043e \u0432\u0440\u0443\u0447\u043d\u0443\u044e') }
    try {
        $o = [ordered]@{}
        $o[(U '\u042d\u0442\u0430\u0436')] = $fl; $o[(U '\u041f\u043e\u043c\u0435\u0449\u0435\u043d\u0438\u0435')] = $rm; $o[(U '\u0420\u0430\u0431\u043e\u0447\u0435\u0435 \u043c\u0435\u0441\u0442\u043e')] = $pl; $o[(U '\u041f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u0435\u043b\u044c')] = $us
        New-Item -ItemType Directory -Force $PassDir | Out-Null; $f = Join-Path $PassDir ('pc_info_' + $env:COMPUTERNAME + '.json')
        [IO.File]::WriteAllText($f, ($o | ConvertTo-Json), (New-Object Text.UTF8Encoding($true)))
        $r.Source = $f + (U ' (\u0441\u043e\u0445\u0440\u0430\u043d\u0435\u043d\u043e)')
    } catch { Write-Host "  cannot save passport: $($_.Exception.Message)" -ForegroundColor Yellow }
    $r
}

function Get-PcPassport {
    $p = [ordered]@{ Floor = ''; Room = ''; Place = ''; User = ''; Source = '' }
    $names = @("pc_info_$env:COMPUTERNAME.json", "pc_info_$env:COMPUTERNAME.txt", 'pc_info.json', 'pc_info.txt', 'pc_info.json.txt', 'pc_info.txt.txt')
    $locs  = (@($PassDir, 'C:\', $Root) + @(Get-DesktopDirs)) | Where-Object { $_ } | Select-Object -Unique
    foreach ($loc in $locs) {
        foreach ($n in $names) {
            $f = Join-Path $loc $n
            if (-not (Test-Path $f -PathType Leaf)) { continue }
            try {
                $v = Read-PassportFile $f
                if ($v) { foreach ($k in 'Floor', 'Room', 'Place', 'User') { $p[$k] = $v[$k] }; $p.Source = $f; break }
                Write-Host "  passport file has no known fields, skipped: $f" -ForegroundColor Yellow
            } catch { Write-Host "  passport file unreadable ($f): $($_.Exception.Message)" -ForegroundColor Yellow }
        }
        if ($p.Source) { break }
    }
    if (-not $p.Source -and -not $NoPrompt -and [Environment]::UserInteractive) {
        $a = Ask-Passport
        if ($a) { foreach ($k in 'Floor', 'Room', 'Place', 'User') { $p[$k] = $a[$k] }; $p.Source = $a.Source }
    }
    $p.UserFromPassport = [bool]$p.User
    if (-not $p.User) { $p.User = $env:USERNAME }
    $p.Pc = $env:COMPUTERNAME
    $p
}

# ===================== EXCEL (OpenXML, no Excel needed) =====================
Add-Type -AssemblyName System.IO.Compression, System.IO.Compression.FileSystem
$XNS  = 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'
$RNS  = 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'
$XSP  = 'http://www.w3.org/XML/1998/namespace'
$UTF8 = New-Object Text.UTF8Encoding($false)

function Col-Letter([int]$n) { $s = ''; while ($n -gt 0) { $m = ($n - 1) % 26; $s = ([string][char](65 + $m)) + $s; $n = [int][math]::Floor(($n - 1) / 26) }; $s }
function Col-Index([string]$l) { $n = 0; foreach ($ch in $l.ToCharArray()) { $n = $n * 26 + ([int][char]$ch - 64) }; $n }

function Read-ZipXml($zip, $name) {
    $e = $zip.GetEntry($name); if (-not $e) { return $null }
    $sr = New-Object IO.StreamReader($e.Open(), $UTF8)
    try { $d = New-Object Xml.XmlDocument; $d.PreserveWhitespace = $true; $d.LoadXml($sr.ReadToEnd()); $d } finally { $sr.Dispose() }
}
function Write-ZipText($zip, $name, [string]$text) {
    if ($zip.Mode -ne [IO.Compression.ZipArchiveMode]::Create) { $e = $zip.GetEntry($name); if ($e) { $e.Delete() } }
    $st = $zip.CreateEntry($name).Open()
    try { $b = $UTF8.GetBytes($text); $st.Write($b, 0, $b.Length) } finally { $st.Dispose() }
}
function Write-ZipXml($zip, $name, $doc) {
    Write-ZipText $zip $name ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>' + "`r`n" + $doc.DocumentElement.OuterXml)
}

function Get-SheetPath($zip) {
    $wb = Read-ZipXml $zip 'xl/workbook.xml'
    $ns = New-Object Xml.XmlNamespaceManager($wb.NameTable); $ns.AddNamespace('m', $XNS)
    $sh = $null; $want = Get-SheetNameRaw      # the configured sheet by name, otherwise the first one
    foreach ($s in @($wb.SelectNodes('//m:sheets/m:sheet', $ns))) { if (-not $sh) { $sh = $s }; if ($s.GetAttribute('name') -ieq $want) { $sh = $s; break } }
    $rid = $sh.GetAttribute('id', $RNS)
    $rels = Read-ZipXml $zip 'xl/_rels/workbook.xml.rels'
    foreach ($rel in $rels.DocumentElement.ChildNodes) {
        if ($rel.NodeType -eq 'Element' -and $rel.GetAttribute('Id') -eq $rid) {
            $t = $rel.GetAttribute('Target')
            if ($t.StartsWith('/')) { return $t.TrimStart('/') } else { return 'xl/' + $t }
        }
    }
    'xl/worksheets/sheet1.xml'
}

function Get-TextOf($node) {
    (@($node.GetElementsByTagName('t') | Where-Object { $_.ParentNode.LocalName -ne 'rPh' } | ForEach-Object { $_.InnerText }) -join '')
}
function Get-CellText($c, $sst) {
    $t = $c.GetAttribute('t')
    if ($t -eq 'inlineStr') { return (Get-TextOf $c) }
    $v = ''
    foreach ($ch in $c.ChildNodes) { if ($ch.LocalName -eq 'v') { $v = $ch.InnerText } }
    if ($t -eq 's' -and $v -ne '') { return $sst[[int]$v] }
    $v
}

function Set-Cell($doc, $row, [int]$colIdx, [string]$text, [string]$style, [bool]$numeric = $false) {
    $cell = $null; $before = $null
    foreach ($c in $row.ChildNodes) {
        if ($c.LocalName -ne 'c') { continue }
        $ci = Col-Index ([regex]::Match($c.GetAttribute('r'), '^[A-Z]+').Value)
        if ($ci -eq $colIdx) { $cell = $c; break }
        if ($ci -gt $colIdx) { $before = $c; break }
    }
    if (-not $cell) {
        $cell = $doc.CreateElement('c', $XNS)
        $cell.SetAttribute('r', (Col-Letter $colIdx) + $row.GetAttribute('r'))
        if ($style) { $cell.SetAttribute('s', $style) }
        if ($before) { [void]$row.InsertBefore($cell, $before) } else { [void]$row.AppendChild($cell) }
    }
    while ($cell.HasChildNodes) { [void]$cell.RemoveChild($cell.FirstChild) }
    [void]$cell.RemoveAttribute('t')
    if ($text -eq '') { return }
    if ($numeric) {
        $cell.SetAttribute('t', 'n')
        $v = $doc.CreateElement('v', $XNS); $v.InnerText = $text; [void]$cell.AppendChild($v)
    } else {
        $cell.SetAttribute('t', 'inlineStr')
        $is = $doc.CreateElement('is', $XNS); $t = $doc.CreateElement('t', $XNS); $t.InnerText = $text
        if ($text -ne $text.Trim()) { $t.SetAttribute('space', $XSP, 'preserve') }
        [void]$is.AppendChild($t); [void]$cell.AppendChild($is)
    }
}

function Get-SheetNameRaw {
    $n = [string](Cfg 'excel.sheetName' (U '\u0418\u043d\u0432\u0435\u043d\u0442\u0430\u0440\u0438\u0437\u0430\u0446\u0438\u044f'))
    $n = $n -replace '[\[\]:*?/\\]', '_'
    if ($n.Length -gt 31) { $n = $n.Substring(0, 31) }
    $n
}
function Get-SheetName { [Security.SecurityElement]::Escape((Get-SheetNameRaw)) }
function New-InventoryXlsx($path, [string[]]$headers) {
    $fs = [IO.File]::Open($path, 'Create', 'ReadWrite', 'None')
    $zip = New-Object IO.Compression.ZipArchive($fs, [IO.Compression.ZipArchiveMode]::Create)
    try {
        Write-ZipText $zip '[Content_Types].xml' ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/></Types>')
        Write-ZipText $zip '_rels/.rels' ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>')
        Write-ZipText $zip 'xl/workbook.xml' ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?><workbook xmlns="' + $XNS + '" xmlns:r="' + $RNS + '"><sheets><sheet name="' + (Get-SheetName) + '" sheetId="1" r:id="rId1"/></sheets></workbook>')
        Write-ZipText $zip 'xl/_rels/workbook.xml.rels' ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>')
        Write-ZipText $zip 'xl/styles.xml' ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?><styleSheet xmlns="' + $XNS + '"><fonts count="2"><font><sz val="11"/><name val="Calibri"/></font><font><b/><sz val="11"/><name val="Calibri"/></font></fonts><fills count="3"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FFD9E1F2"/></patternFill></fill></fills><borders count="2"><border><left/><right/><top/><bottom/><diagonal/></border><border><left style="thin"/><right style="thin"/><top style="thin"/><bottom style="thin"/><diagonal/></border></borders><cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs><cellXfs count="3"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/><xf numFmtId="0" fontId="1" fillId="2" borderId="1" xfId="0" applyFont="1" applyFill="1" applyBorder="1" applyAlignment="1"><alignment horizontal="center" vertical="center" wrapText="1"/></xf><xf numFmtId="0" fontId="0" fillId="0" borderId="1" xfId="0" applyBorder="1" applyAlignment="1"><alignment horizontal="left" vertical="center" wrapText="1"/></xf></cellXfs></styleSheet>')
        $cols = ''; $w = 12, 10, 13, 15, 24, 14, 14, 26, 36, 18, 22
        for ($i = 0; $i -lt $headers.Count; $i++) { $cols += '<col min="' + ($i + 1) + '" max="' + ($i + 1) + '" width="' + $w[$i] + '" customWidth="1"/>' }
        $h = ''
        for ($i = 0; $i -lt $headers.Count; $i++) { $h += '<c r="' + (Col-Letter ($i + 1)) + '1" s="1" t="inlineStr"><is><t>' + [Security.SecurityElement]::Escape($headers[$i]) + '</t></is></c>' }
        Write-ZipText $zip 'xl/worksheets/sheet1.xml' ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="' + $XNS + '"><dimension ref="A1:' + (Col-Letter $headers.Count) + '1"/><sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><sheetFormatPr defaultRowHeight="15"/><cols>' + $cols + '</cols><sheetData><row r="1" ht="28" customHeight="1">' + $h + '</row></sheetData></worksheet>')
    } finally { $zip.Dispose(); $fs.Dispose() }
}

# ---- merge rules: never destroy manual data with a weaker detection ----
function Merge-Id($old, $new, $none) {
    $weak = @($none, $script:NoId)
    if ($new -and ($weak -notcontains $new)) { return $new }        # a real ID always wins
    if ($old -and ($weak -notcontains $old)) { return $old }        # a real or hand-typed value is never replaced by "none" / "ID not found"
    if ($new) { return $new }
    if ($old) { return $old }
    $none
}
function Get-DiskProtectionNames {       # product names known to the detector (built-in + config.json)
    $n = @($script:Sig.Disk.Keys) + 'Windows UWF'
    foreach ($d in @(Cfg 'diskProtectionDetect.disableBuiltin' @())) { $n = @($n | Where-Object { $_ -ne [string]$d }) }
    foreach ($xp in @(Cfg 'diskProtectionDetect.extraProducts' @())) { if ($xp.name) { $n += [string]$xp.name } }
    $n
}
function Merge-DiskProtection($old, $new, $none) {
    $names = @(Get-DiskProtectionNames | ForEach-Object { [regex]::Escape($_) })
    $prod = $(if ($names.Count) { '^(' + ($names -join '|') + ')' } else { '^(?!)' })
    if ($new -ne $none) {
        $p = [regex]::Match($new, $prod).Value
        if ($old -and $p -and $old.StartsWith($p)) { return $old }   # product is the same: keep the state a human wrote (the protected / unprotected state cannot be detected)
        return $new
    }
    if ($old -and $old -match ($prod + '|' + (U '\u0417\u0430\u0449\u0438\u0442\u0430'))) { return $none }   # software is gone
    if ($old) { return $old }                                                                                               # manual note 
    $none
}

# ---- hyperlink cell: =HYPERLINK("relative\path.html","label"), relative to the workbook folder (survives a changed drive letter) ----
function Add-LinkStyle($zip, [string]$baseIdx, [bool]$asLink = $true) {
    try {
        $sd = Read-ZipXml $zip 'xl/styles.xml'; if (-not $sd) { return '' }
        $sn = New-Object Xml.XmlNamespaceManager($sd.NameTable); $sn.AddNamespace('m', $XNS)
        $fonts = $sd.SelectSingleNode('//m:fonts', $sn); $fills = $sd.SelectSingleNode('//m:fills', $sn); $xfs = $sd.SelectSingleNode('//m:cellXfs', $sn)
        function El($n, $attrs) { $e = $sd.CreateElement($n, $XNS); foreach ($k in $attrs.Keys) { $e.SetAttribute($k, $attrs[$k]) }; $e }
        $pf = El 'patternFill' @{ patternType = 'solid' }
        [void]$pf.AppendChild((El 'fgColor' @{ rgb = 'FFE2EFDA' })); [void]$pf.AppendChild((El 'bgColor' @{ indexed = '64' }))
        $fill = El 'fill' @{}; [void]$fill.AppendChild($pf); [void]$fills.AppendChild($fill)
        $fln = @($fills.ChildNodes | Where-Object { $_.NodeType -eq 'Element' }).Count
        $fills.SetAttribute('count', [string]$fln)
        $xl = @($xfs.ChildNodes | Where-Object { $_.LocalName -eq 'xf' })
        $bi = 0; if ($baseIdx -ne '' -and [int]$baseIdx -lt $xl.Count) { $bi = [int]$baseIdx }
        $nx = $xl[$bi].CloneNode($true)
        $nx.SetAttribute('fillId', [string]($fln - 1)); $nx.SetAttribute('applyFill', '1')
        if ($asLink) {
            $font = El 'font' @{}
            [void]$font.AppendChild((El 'u' @{})); [void]$font.AppendChild((El 'sz' @{ val = '11' }))
            [void]$font.AppendChild((El 'color' @{ rgb = 'FF0563C1' })); [void]$font.AppendChild((El 'name' @{ val = 'Calibri' }))
            [void]$fonts.AppendChild($font)
            $fn = @($fonts.ChildNodes | Where-Object { $_.NodeType -eq 'Element' }).Count
            $fonts.SetAttribute('count', [string]$fn)
            $nx.SetAttribute('fontId', [string]($fn - 1)); $nx.SetAttribute('applyFont', '1')
        }
        [void]$xfs.AppendChild($nx)
        $xfs.SetAttribute('count', [string]($xl.Count + 1))
        Write-ZipXml $zip 'xl/styles.xml' $sd
        return [string]$xl.Count
    } catch { return '' }
}
function Get-LinkStyleOf($row, [int]$colIdx) {      # reuse the style of an existing link cell (do not grow styles.xml on every run)
    $ref = (Col-Letter $colIdx) + $row.GetAttribute('r')
    $c = $row.ChildNodes | Where-Object { $_.LocalName -eq 'c' -and $_.GetAttribute('r') -eq $ref } | Select-Object -First 1
    if ($c -and $c.GetAttribute('s') -and @($c.ChildNodes | Where-Object { $_.LocalName -eq 'f' }).Count) { return $c.GetAttribute('s') }
    ''
}
function Set-LinkCell($doc, $row, [int]$colIdx, [string]$rel, [string]$label, [string]$style) {
    Set-Cell $doc $row $colIdx $label $style
    $ref = (Col-Letter $colIdx) + $row.GetAttribute('r')
    $cell = $row.ChildNodes | Where-Object { $_.LocalName -eq 'c' -and $_.GetAttribute('r') -eq $ref } | Select-Object -First 1
    while ($cell.HasChildNodes) { [void]$cell.RemoveChild($cell.FirstChild) }
    $cell.SetAttribute('t', 'str')
    if ($style) { $cell.SetAttribute('s', $style) }
    $f = $doc.CreateElement('f', $XNS); $f.InnerText = 'HYPERLINK("' + $rel.Replace('"', '""') + '","' + $label.Replace('"', '""') + '")'
    $v = $doc.CreateElement('v', $XNS); $v.InnerText = $label
    [void]$cell.AppendChild($f); [void]$cell.AppendChild($v)
}

function Get-MergeRanges($doc, $ns) {
    $r = @()
    foreach ($m in @($doc.SelectNodes('//m:mergeCells/m:mergeCell', $ns))) {
        $x = [regex]::Match($m.GetAttribute('ref'), '^([A-Z]+)(\d+)(?::([A-Z]+)(\d+))?$')
        if (-not $x.Success -or -not $x.Groups[3].Success) { continue }
        $r += [pscustomobject]@{ C1 = (Col-Index $x.Groups[1].Value); R1 = [int]$x.Groups[2].Value; C2 = (Col-Index $x.Groups[3].Value); R2 = [int]$x.Groups[4].Value }
    }
    $r
}
function Find-MergeAt($merges, [int]$rn, [int]$col) {
    $merges | Where-Object { $_.R1 -le $rn -and $_.R2 -ge $rn -and $_.C1 -le $col -and $_.C2 -ge $col } | Select-Object -First 1
}

# writes one cell only when its text really changes; never erases with an empty value, never overwrites a formula,
# keeps a number a number (a manually typed floor "2" must not turn into text)
function Set-CellIf($doc, $row, [int]$col, [string]$old, [string]$new, [string]$style) {
    if ($col -le 0 -or $new -eq '' -or $old -ceq $new) { return $false }
    $ref = (Col-Letter $col) + $row.GetAttribute('r')
    $cell = $row.ChildNodes | Where-Object { $_.LocalName -eq 'c' -and $_.GetAttribute('r') -eq $ref } | Select-Object -First 1
    if ($cell -and @($cell.ChildNodes | Where-Object { $_.LocalName -eq 'f' }).Count) { Write-Log WARN "excel: $ref holds a formula, left as is"; return $false }
    $num = $false
    if ($cell -and $new -match '^\d{1,9}$' -and ($cell.GetAttribute('t') -eq '' -or $cell.GetAttribute('t') -eq 'n') -and $old -match '^\d+$') { $num = $true }
    Set-Cell $doc $row $col $new $style $num
    $true
}

# the worksheet part: copy, update, verify, then replace the original (a failure half-way never damages the workbook)
# self-check before the sheet is saved: any failure throws, the workbook is then NOT replaced (row goes to _pending_rows.csv)
function Test-InventoryDoc($zip, $doc, $ns, $data, $row, [int]$pcCol, [string]$pc) {
    if ($pcCol -le 0) { throw 'self-check: PC name column was not resolved' }
    $seen = @{}; $prev = 0
    foreach ($r in @($data.ChildNodes | Where-Object { $_.LocalName -eq 'row' })) {
        $rn = 0; if (-not [int]::TryParse($r.GetAttribute('r'), [ref]$rn) -or $rn -le $prev) { throw "self-check: row numbers are not unique / ascending (row '$($r.GetAttribute('r'))')" }
        $prev = $rn; $pc0 = 0
        foreach ($x in @($r.ChildNodes | Where-Object { $_.LocalName -eq 'c' })) {
            $m = [regex]::Match($x.GetAttribute('r'), '^([A-Z]+)(\d+)$')
            if (-not $m.Success -or [int]$m.Groups[2].Value -ne $rn) { throw "self-check: bad cell reference '$($x.GetAttribute('r'))' in row $rn" }
            $ci = Col-Index $m.Groups[1].Value
            if ($ci -le $pc0) { throw "self-check: cells out of order in row $rn" }
            $pc0 = $ci
        }
    }
    $cr = $row.ChildNodes | Where-Object { $_.LocalName -eq 'c' -and $_.GetAttribute('r') -eq ((Col-Letter $pcCol) + $row.GetAttribute('r')) } | Select-Object -First 1
    if (-not $cr -or (Get-TextOf $cr) -ne $pc) { throw 'self-check: the written row does not contain the PC name' }
    foreach ($cl in @($doc.SelectNodes('//m:cols/m:col', $ns))) {
        $mn = 0; $mx = 0
        if (-not [int]::TryParse($cl.GetAttribute('min'), [ref]$mn) -or -not [int]::TryParse($cl.GetAttribute('max'), [ref]$mx) -or $mn -lt 1 -or $mx -lt $mn) { throw 'self-check: a <col> element has no valid min/max' }
    }
    $sd = Read-ZipXml $zip 'xl/styles.xml'
    if ($sd) {
        $sn = New-Object Xml.XmlNamespaceManager($sd.NameTable); $sn.AddNamespace('m', $XNS)
        foreach ($pair in @(@('fonts', 'font'), @('fills', 'fill'), @('borders', 'border'), @('cellXfs', 'xf'))) {
            $nd = $sd.SelectSingleNode('//m:' + $pair[0], $sn)
            if ($nd -and [int]$nd.GetAttribute('count') -ne @($nd.ChildNodes | Where-Object { $_.LocalName -eq $pair[1] }).Count) { throw "self-check: styles.xml <$($pair[0])> count does not match its items" }
        }
        $nx = @($sd.SelectNodes('//m:cellXfs/m:xf', $sn)).Count
        foreach ($x in @($doc.SelectNodes('//m:c[@s]', $ns))) { if ([int]$x.GetAttribute('s') -ge $nx) { throw "self-check: cell $($x.GetAttribute('r')) uses a style that does not exist" } }
    }
}

function Write-InventoryRow($file, $headers, $builtin, $rec, $none, [bool]$created) {
    $keys = 'Num', 'Floor', 'Room', 'Place', 'User', 'RemoteA', 'RemoteB', 'State', 'Disk', 'Pc', 'Rpt'
    $fs = [IO.File]::Open($file, 'Open', 'ReadWrite', 'None')
    $zip = New-Object IO.Compression.ZipArchive($fs, [IO.Compression.ZipArchiveMode]::Update)
    try {
        $sp  = Get-SheetPath $zip
        $doc = Read-ZipXml $zip $sp
        if (-not $doc) { throw "worksheet '$sp' was not found in the workbook" }
        $ns = New-Object Xml.XmlNamespaceManager($doc.NameTable); $ns.AddNamespace('m', $XNS)
        $prot = $doc.SelectSingleNode('//m:sheetProtection', $ns)
        if ($prot -and $prot.GetAttribute('sheet') -match '^(1|true)$') { throw 'the sheet is protected (Excel: Review > Unprotect Sheet); the row was not written' }
        $merges = @(Get-MergeRanges $doc $ns)
        $sst = @(); $sd = Read-ZipXml $zip 'xl/sharedStrings.xml'
        if ($sd) { foreach ($si in $sd.DocumentElement.ChildNodes) { if ($si.LocalName -eq 'si') { $sst += (Get-TextOf $si) } } }
        $data = $doc.SelectSingleNode('//m:sheetData', $ns)
        $rows = @($data.ChildNodes | Where-Object { $_.LocalName -eq 'row' })

        # known header texts per field (config titles and built-in ones)
        $known = @{}; $all = @()
        for ($i = 0; $i -lt $keys.Count; $i++) {
            $known[$keys[$i]] = @(@($headers[$i], $builtin[$i]) | ForEach-Object { ([string]$_).Trim().ToLower() } | Select-Object -Unique)
            $all += $known[$keys[$i]]
        }
        # header row: normally row 1, but a few title rows above it are tolerated
        $hdrN = 1; $best = 0
        foreach ($r in ($rows | Where-Object { [int]$_.GetAttribute('r') -le 10 })) {
            $hit = 0
            foreach ($c in $r.ChildNodes) { if ($c.LocalName -eq 'c') { $tx = (Get-CellText $c $sst).Trim().ToLower(); if ($tx -and ($all -contains $tx)) { $hit++ } } }
            if ($hit -gt $best) { $best = $hit; $hdrN = [int]$r.GetAttribute('r') }
        }
        if ($best -lt 2) { $hdrN = 1 }
        $hdr = $rows | Where-Object { [int]$_.GetAttribute('r') -eq $hdrN } | Select-Object -First 1

        $hmap = @{}; $hText = @{}; $maxCol = 0; $lastHdrStyle = ''
        if ($hdr) {
            foreach ($c in $hdr.ChildNodes) {
                if ($c.LocalName -ne 'c') { continue }
                $ci = Col-Index ([regex]::Match($c.GetAttribute('r'), '^[A-Z]+').Value)
                if ($ci -gt $maxCol) { $maxCol = $ci }
                if ($c.GetAttribute('s')) { $lastHdrStyle = $c.GetAttribute('s') }
                $tx = (Get-CellText $c $sst).Trim()
                if ($tx) { $hText[$ci] = $tx; if (-not $hmap.ContainsKey($tx.ToLower())) { $hmap[$tx.ToLower()] = $ci } }
            }
        }
        # field -> column by header text, so inserted / reordered columns do not matter
        $Cm = @{}
        foreach ($k in $keys) { $Cm[$k] = 0; foreach ($t in $known[$k]) { if ($hmap.ContainsKey($t)) { $Cm[$k] = $hmap[$t]; break } } }
        for ($i = 0; $i -lt 9; $i++) {      # legacy position only into an EMPTY header cell; a column that holds anything else is never used
            $k = $keys[$i]
            if ($Cm[$k]) { continue }
            if (-not $hdr) { $Cm[$k] = $i + 1; continue }
            if (-not $hText.ContainsKey($i + 1)) { $Cm[$k] = $i + 1; Set-Cell $doc $hdr ($i + 1) $headers[$i] $lastHdrStyle; if ($i + 1 -gt $maxCol) { $maxCol = $i + 1 } }
            else { Write-Log WARN "excel: column '$($headers[$i])' is not in the header row (column $($i + 1) is '$($hText[$i + 1])'): this field is not written" }
        }
        $rptNew = $false
        if (-not $Cm.Pc) { $Cm.Pc = [math]::Max($maxCol + 1, 10); if ($hdr) { Set-Cell $doc $hdr $Cm.Pc $headers[9] $lastHdrStyle }; $maxCol = [math]::Max($maxCol, $Cm.Pc) }
        if (-not $Cm.Rpt) {
            $Cm.Rpt = [math]::Max($maxCol + 1, 11); $rptNew = $true
            if ($hdr) { $hs = Add-LinkStyle $zip $lastHdrStyle $false; Set-Cell $doc $hdr $Cm.Rpt $headers[10] $(if ($hs) { $hs } else { $lastHdrStyle }) }
        }

        # model of existing data rows
        $items = @()
        foreach ($r in $rows) {
            $rn = [int]$r.GetAttribute('r'); if ($rn -le $hdrN) { continue }
            $v = @{}
            foreach ($c in $r.ChildNodes) {
                if ($c.LocalName -ne 'c') { continue }
                $v[(Col-Index ([regex]::Match($c.GetAttribute('r'), '^[A-Z]+').Value))] = (Get-CellText $c $sst).Trim()
            }
            if (($v.Values | Where-Object { $_ }).Count -eq 0) { continue }
            $items += [pscustomobject]@{ Node = $r; N = $rn; V = $v }
        }
        function Cv($it, $i) { if ($i -gt 0 -and $it.V.ContainsKey($i)) { $it.V[$i] } else { '' } }
        $same = { param($a, $b) $a -and $b -and ($a.Trim() -ieq $b.Trim()) }

        # find existing row: PC name > remote access ID > floor+room+place > user (only if unique and has no PC name yet)
        $hit = $null; $how = ''
        $hit = $items | Where-Object { & $same (Cv $_ $Cm.Pc) $rec.Pc } | Select-Object -First 1; if ($hit) { $how = 'PC name' }
        if (-not $hit -and $Cm.RemoteA -and $rec.RemoteA -ne $none -and $rec.RemoteA -ne $script:NoId) { $hit = $items | Where-Object { (Cv $_ $Cm.RemoteA) -eq $rec.RemoteA } | Select-Object -First 1; if ($hit) { $how = 'remote access ID' } }
        if (-not $hit -and $Cm.Floor -and $Cm.Room -and $Cm.Place -and $rec.Floor -and $rec.Room -and $rec.Place) {
            $hit = $items | Where-Object { (& $same (Cv $_ $Cm.Floor) $rec.Floor) -and (& $same (Cv $_ $Cm.Room) $rec.Room) -and (& $same (Cv $_ $Cm.Place) $rec.Place) } | Select-Object -First 1
            if ($hit) { $how = 'floor/room/place' }
        }
        if (-not $hit -and $Cm.User -and $rec.User) {
            $cand = @($items | Where-Object { (& $same (Cv $_ $Cm.User) $rec.User) -and -not (Cv $_ $Cm.Pc) })
            if ($cand.Count -eq 1) { $hit = $cand[0]; $how = 'user' }
        }
        $lastRow = ($rows | ForEach-Object { [int]$_.GetAttribute('r') } | Measure-Object -Maximum).Maximum
        if (-not $lastRow) { $lastRow = $hdrN }
        foreach ($m in $merges) { if ($m.R2 -gt $lastRow) { $lastRow = $m.R2 } }       # never write into (or under) a merged block

        $writeCols = @($Cm.Values | Where-Object { $_ })
        if ($hit) {
            $row = $hit.Node
            foreach ($cc in $writeCols) { $mg = Find-MergeAt $merges $hit.N $cc; if ($mg) { throw "cell $(Col-Letter $cc)$($hit.N) is inside a merged range; the row was not written (unmerge the cells)" } }
            $st = @{}; foreach ($c in $row.ChildNodes) { if ($c.LocalName -eq 'c') { $st[(Col-Index ([regex]::Match($c.GetAttribute('r'), '^[A-Z]+').Value))] = $c.GetAttribute('s') } }
            $sty = { param($i) if ($st.ContainsKey($i)) { $st[$i] } elseif ($st.Count) { ($st.Values | Select-Object -First 1) } else { '' } }
            $n = @{}
            $n.Floor = if ($rec.Floor) { $rec.Floor } else { Cv $hit $Cm.Floor }
            $n.Room  = if ($rec.Room)  { $rec.Room }  else { Cv $hit $Cm.Room }
            $n.Place = if ($rec.Place) { $rec.Place } else { Cv $hit $Cm.Place }
            $n.User  = if ($rec.UserFromPassport -or -not (Cv $hit $Cm.User)) { $rec.User } else { Cv $hit $Cm.User }
            $n.RemoteA   = Merge-Id (Cv $hit $Cm.RemoteA) $rec.RemoteA $none
            $n.RemoteB   = Merge-Id (Cv $hit $Cm.RemoteB) $rec.RemoteB $none
            $n.State = if (Cv $hit $Cm.State) { Cv $hit $Cm.State } else { $rec.State }
            $n.Disk = Merge-DiskProtection (Cv $hit $Cm.Disk) $rec.Disk $none
            $n.Pc    = $rec.Pc
            $changed = 0
            foreach ($k in 'Floor', 'Room', 'Place', 'User', 'RemoteA', 'RemoteB', 'State', 'Disk', 'Pc') {
                if (Set-CellIf $doc $row $Cm[$k] (Cv $hit $Cm[$k]) ([string]$n[$k]) (& $sty $Cm[$k])) { $changed++ }
            }
            [void]$row.RemoveAttribute('spans')
            if ($rec.ReportRel -and $Cm.Rpt) { $ls = Get-LinkStyleOf $row $Cm.Rpt; if (-not $ls) { $ls = Add-LinkStyle $zip (& $sty $Cm.Pc) $true }; Set-LinkCell $doc $row $Cm.Rpt $rec.ReportRel $rec.ReportLabel $ls }
            $result = "updated row $($hit.N) (match: $how; cells changed: $changed)"
            $last = $lastRow
        } else {
            $new = $lastRow + 1
            foreach ($cc in $writeCols) { $mg = Find-MergeAt $merges $new $cc; if ($mg) { throw "the new row $new would fall into a merged range; the row was not written" } }
            $num = ($items | ForEach-Object { $x = 0; if ([int]::TryParse((Cv $_ $Cm.Num), [ref]$x)) { $x } else { 0 } } | Measure-Object -Maximum).Maximum
            $src = $items | Where-Object { $_.N -eq $lastRow } | Select-Object -First 1; if (-not $src) { $src = $items | Select-Object -Last 1 }
            $st = @{}; if ($src) { foreach ($c in $src.Node.ChildNodes) { if ($c.LocalName -eq 'c') { $st[(Col-Index ([regex]::Match($c.GetAttribute('r'), '^[A-Z]+').Value))] = $c.GetAttribute('s') } } }
            $sty = { param($i) if ($st.ContainsKey($i)) { $st[$i] } elseif ($created) { '2' } else { '' } }
            $row = $doc.CreateElement('row', $XNS); $row.SetAttribute('r', [string]$new); [void]$data.AppendChild($row)
            if ($Cm.Num) { Set-Cell $doc $row $Cm.Num ([string]([int]$num + 1)) (& $sty $Cm.Num) $true }
            $vals = @{ Floor = $rec.Floor; Room = $rec.Room; Place = $rec.Place; User = $rec.User; RemoteA = $rec.RemoteA; RemoteB = $rec.RemoteB; State = $rec.State; Disk = $rec.Disk; Pc = $rec.Pc }
            foreach ($k in $vals.Keys) { if ($Cm[$k]) { Set-Cell $doc $row $Cm[$k] ([string]$vals[$k]) (& $sty $Cm[$k]) } }
            if ($rec.ReportRel -and $Cm.Rpt) { $ls = Get-LinkStyleOf $row $Cm.Rpt; if (-not $ls) { $ls = Add-LinkStyle $zip (& $sty $Cm.Pc) $true }; Set-LinkCell $doc $row $Cm.Rpt $rec.ReportRel $rec.ReportLabel $ls }
            $last = $new
            $result = "added row $new (#$([int]$num + 1))"
        }

        # new report column: paint the empty cells of existing rows too, so the whole column has its own colour
        if ($rptNew) {
            $fsty = Add-LinkStyle $zip (& $sty $Cm.Pc) $false
            foreach ($rw in @($data.ChildNodes | Where-Object { $_.LocalName -eq 'row' })) {
                $rn = [int]$rw.GetAttribute('r'); if ($rn -le $hdrN) { continue }
                if (Find-MergeAt $merges $rn $Cm.Rpt) { continue }
                $ref = (Col-Letter $Cm.Rpt) + $rn
                $has = $rw.ChildNodes | Where-Object { $_.LocalName -eq 'c' -and $_.GetAttribute('r') -eq $ref } | Select-Object -First 1
                if (-not $has -and $fsty) { Set-Cell $doc $rw $Cm.Rpt '' $fsty; [void]$rw.RemoveAttribute('spans') }
            }
        }

        # dimension / autofilter (its own start cell is kept) / column width
        $lastCol = [math]::Max($maxCol, [math]::Max($Cm.Pc, $Cm.Rpt))
        $dim = $doc.SelectSingleNode('//m:dimension', $ns)
        if ($dim) { $dim.SetAttribute('ref', 'A1:' + (Col-Letter $lastCol) + [math]::Max($last, $lastRow)) }
        $af = $doc.SelectSingleNode('//m:autoFilter', $ns)
        if ($af -and $af.GetAttribute('ref')) {
            $a0 = [regex]::Match($af.GetAttribute('ref'), '^[A-Z]+\d+').Value; if (-not $a0) { $a0 = 'A' + $hdrN }
            $af.SetAttribute('ref', $a0 + ':' + (Col-Letter $lastCol) + [math]::Max($last, $lastRow))
        }
        $colsN = $doc.SelectSingleNode('//m:cols', $ns)
        foreach ($cc in @($Cm.Pc, $Cm.Rpt)) {
            if ($colsN -and -not ($colsN.ChildNodes | Where-Object { $_.NodeType -eq 'Element' -and [int]$_.GetAttribute('min') -le $cc -and [int]$_.GetAttribute('max') -ge $cc })) {
                $cn = $doc.CreateElement('col', $XNS); $cn.SetAttribute('min', [string]$cc); $cn.SetAttribute('max', [string]$cc)
                $cn.SetAttribute('width', $(if ($cc -eq $Cm.Rpt) { '22' } else { '18' })); $cn.SetAttribute('customWidth', '1'); [void]$colsN.AppendChild($cn)
            }
        }
        Test-InventoryDoc $zip $doc $ns $data $row $Cm.Pc ([string]$rec.Pc)
        Write-ZipXml $zip $sp $doc
    } finally { $zip.Dispose(); $fs.Dispose() }
    $result
}

function Update-InventoryXlsx($path, $rec, $none) {
    $builtin = @('#', '\u042d\u0442\u0430\u0436', '\u041f\u043e\u043c\u0435\u0449\u0435\u043d\u0438\u0435', '\u0420\u0430\u0431\u043e\u0447\u0435\u0435 \u043c\u0435\u0441\u0442\u043e', '\u041f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u0435\u043b\u044c', '\u0423\u0434\u0430\u043b\u0451\u043d\u043d\u044b\u0439 \u0434\u043e\u0441\u0442\u0443\u043f 1 (ID)', '\u0423\u0434\u0430\u043b\u0451\u043d\u043d\u044b\u0439 \u0434\u043e\u0441\u0442\u0443\u043f 2 (ID)', '\u0421\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u0435 \u0440\u0430\u0431\u043e\u0447\u0435\u0439 \u0441\u0442\u0430\u043d\u0446\u0438\u0438', '\u0417\u0430\u0449\u0438\u0442\u0430 \u0434\u0438\u0441\u043a\u0430', '\u0418\u043c\u044f \u041f\u041a', '\u041e\u0442\u0447\u0451\u0442') | ForEach-Object { U $_ }
    $headers = @($builtin)
    $hc = @(Cfg 'excel.headers' @())      # config.json: custom column titles (used when a NEW workbook is created; existing sheets are matched by header text)
    if ($hc.Count -eq $headers.Count) { $headers = @($hc | ForEach-Object { [string]$_ }) }
    elseif ($hc.Count) { Write-Host "  excel.headers must contain $($headers.Count) items, built-in headers are used" -ForegroundColor Yellow }

    if (-not (Test-Path -LiteralPath $path)) {
        New-InventoryXlsx $path $headers
        $rr = @(Write-InventoryRow $path $headers $builtin $rec $none $true)
        return ('created file; ' + [string]$rr[-1])
    }
    $probe = [IO.File]::Open($path, 'Open', 'ReadWrite', 'None'); $probe.Dispose()      # throws if the file is open in Excel
    $bk = Join-Path $OutDir '_backup'
    New-Item -ItemType Directory -Force $bk | Out-Null
    Copy-Item -LiteralPath $path (Join-Path $bk ([IO.Path]::GetFileNameWithoutExtension($path) + '_' + (Get-Date -Format 'yyyyMMdd_HHmmss') + '.xlsx')) -Force
    Get-ChildItem $bk -Filter '*.xlsx' | Sort-Object LastWriteTime -Descending | Select-Object -Skip ([int](Cfg 'backup.keep' 10)) | Remove-Item -Force -ErrorAction SilentlyContinue
    $tmp = $path + '.tmp'
    try {
        Copy-Item -LiteralPath $path -Destination $tmp -Force
        $rr = @(Write-InventoryRow $tmp $headers $builtin $rec $none $false); $result = [string]$rr[-1]
        $vz = [IO.Compression.ZipFile]::OpenRead($tmp)       # the updated copy must open and parse before it replaces the original
        try { [void](Read-ZipXml $vz (Get-SheetPath $vz)) } finally { $vz.Dispose() }
        [IO.File]::Copy($tmp, $path, $true)
    } finally { if (Test-Path -LiteralPath $tmp) { Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue } }
    $result
}

# ===================== INVENTORY -> EXCEL =====================
function Find-XlsxPath {
    $custom = Cfg 'paths.workbook' $null
    if ($custom) { return (RootPath ([string]$custom)) }
    $name = (U '\u0418\u043d\u0432\u0435\u043d\u0442\u0430\u0440\u0438\u0437\u0430\u0446\u0438\u044f') + '.xlsx'
    $p = Join-Path $Root $name
    if (Test-Path $p) { return $p }
    $f = Get-ChildItem $Root -Filter ((U '\u0418\u043d\u0432\u0435\u043d\u0442\u0430\u0440\u0438\u0437\u0430\u0446\u0438\u044f') + '*.xlsx') -File -ErrorAction SilentlyContinue |
         Where-Object { $_.Name -notlike '~$*' } | Select-Object -First 1
    if ($f) { return $f.FullName }
    $p
}

function Save-PendingRow($rec) {
    $f = Join-Path $OutDir '_pending_rows.csv'
    $isNew = -not (Test-Path $f)
    $esc = { param($s) '"' + ([string]$s).Replace('"', '""') + '"' }
    $line = (@($rec.Floor, $rec.Room, $rec.Place, $rec.User, $rec.RemoteA, $rec.RemoteB, $rec.State, $rec.Disk, $rec.Pc, (Get-Date -Format 'yyyy-MM-dd HH:mm')) | ForEach-Object { & $esc $_ }) -join ';'
    $txt = ''
    if ($isNew) { $txt = '"Floor";"Room";"Place";"User";"RemoteAccessA";"RemoteAccessB";"State";"DiskProtection";"PC";"Collected"' + "`r`n" }
    [IO.File]::AppendAllText($f, $txt + $line + "`r`n", (New-Object Text.UTF8Encoding($true)))
    $f
}

# returns 0 ok, 5 Excel not updated
function Invoke-Inventory {
    Write-Host '--- inventory ---'
    $pp  = Get-PcPassport
    $rec = [pscustomobject]@{
        Floor = $pp.Floor; Room = $pp.Room; Place = $pp.Place; User = $pp.User; UserFromPassport = $pp.UserFromPassport
        RemoteA = $(if (Cfg 'features.remoteAccessDetect' $true) { Tm 'RemoteA' { Get-RemoteIdA } } else { $NO }); RemoteB = $(if (Cfg 'features.remoteAccessDetect' $true) { Tm 'RemoteB' { Get-RemoteIdB } } else { $NO }); State = [string](Cfg 'excel.defaultState' (U '\u0425\u043e\u0440\u043e\u0448\u0435\u0435'))
        Disk = $(if (Cfg 'features.diskProtectionDetect' $true) { Tm 'DiskProtection' { Get-DiskProtectionStatus } } else { $NO }); Pc = $env:COMPUTERNAME; ReportRel = ''; ReportLabel = ''
    }
    function Via($x) { if ($x) { "<- $x" } else { '<- not found' } }
    Write-Host "  passport  : $(if ($pp.Source) { $pp.Source } else { 'not found (C:\, USB root, desktops), using Windows user name' })"
    Write-Host "  PC / user : $($rec.Pc) / $($rec.User)"
    Write-Host "  floor/room/place : $($rec.Floor) / $($rec.Room) / $($rec.Place)"
    Write-Host "  remote A  : $($rec.RemoteA)  $(Via $script:Src.RemoteA)"
    Write-Host "  remote B  : $($rec.RemoteB)  $(Via $script:Src.RemoteB)"
    Write-Host "  disk prot.: $($rec.Disk)  $(Via $script:Src.Disk)"

    $xl = Find-XlsxPath
    foreach ($c in @($Out)) {
        if ((Test-Path $c) -and ((Get-Item $c).Length -gt 0)) {
            $base = (Split-Path $xl).TrimEnd('\') + '\'
            $rec.ReportRel   = $(if ($c.StartsWith($base, [StringComparison]::OrdinalIgnoreCase)) { $c.Substring($base.Length) } else { $c })
            $rec.ReportLabel = ([string](Cfg 'excel.reportLabel' (U '\u041e\u0442\u0447\u0451\u0442'))) + ' ' + (Get-Date -Format ([string](Cfg 'excel.labelDateFormat' 'yyyy-MM-dd')))
            Write-Host "  report link: $($rec.ReportRel)"
            break
        }
    }
    try { $rec | ConvertTo-Json | Out-File (Join-Path $OutDir '_last_inventory.json') -Encoding utf8 } catch { }      # after the report link is known
    try {
        $res = Update-InventoryXlsx $xl $rec $NO
        Write-Host "  Excel     : $res  [$xl]" -ForegroundColor Green
        return 0
    } catch {
        Write-Host "  Excel NOT updated: $($_.Exception.Message)" -ForegroundColor Red
        if ($_.Exception.Message -match 'protected|merged|self-check') { Write-Host '  (fix the table as described above and run again; nothing was changed in the workbook)' -ForegroundColor Yellow }
        else { Write-Host '  (if the file is open in Excel - close it and run again; the workbook was not changed)' -ForegroundColor Yellow }
        $pf = Save-PendingRow $rec
        Write-Host "  row saved to: $pf" -ForegroundColor Yellow
        return 5
    }
}

# ======================= MAIN =======================
New-Item -ItemType Directory -Force $OutDir | Out-Null
try { Start-Transcript -Path (Join-Path $OutDir '_last_run.log') -Force | Out-Null } catch { }
Write-Host "$AppName v$AppVer" -ForegroundColor Cyan
if (-not (Test-IsAdmin)) { Write-Log WARN 'Not running as Administrator: service profiles, some WMI classes and disk details may be unavailable. Use Inspektor.bat (it asks for elevation).' }
if ($Diagnose) { Write-Log INFO 'Diagnose mode: collecting a detailed log' }

$invRc = 0; $rptRc = 0; $t0all = Get-Date
if (-not $SkipReport) {            # report first: its file name goes into the Excel row as a link
    try { New-InspectorReport $Out; Write-Host "Report    : $Out" -ForegroundColor Green }
    catch { Write-Host "Report failed: $($_.Exception.Message)" -ForegroundColor Red; $rptRc = 3 }
}
if (-not $SkipExcel) {
    try { $invRc = Invoke-Inventory } catch { Write-Host "Inventory error: $($_.Exception.Message)" -ForegroundColor Red; $invRc = 5 }
}

Write-Host ''
Write-Host "Result: report=$rptRc, inventory=$invRc, total $([int]((Get-Date) - $t0all).TotalSeconds)s"
if ($Diagnose) { try { Write-Host "Diagnose  : $(Save-DiagnoseLog $OutDir)" -ForegroundColor Cyan } catch { Write-Host "Diagnose log failed: $($_.Exception.Message)" -ForegroundColor Red } }
if ($invRc -eq 5) { Write-Host "Excel was NOT updated. Close the .xlsx file and run again. Row saved to: $(Join-Path $OutDir '_pending_rows.csv')" -ForegroundColor Yellow }
if ($rptRc -eq 0 -and $invRc -eq 0) {
    if ((Cfg 'ui.openReportWhenDone' $true) -and -not $SkipReport -and (Test-Path $Out)) { try { Start-Process $Out } catch { } }
    elseif (Cfg 'ui.openFolderWhenDone' $true) { try { Start-Process explorer.exe -ArgumentList ('"' + $OutDir + '"') } catch { } }
}
if ($rptRc -ne 0) { Finish $rptRc }
if ($invRc -ne 0) { Finish $invRc }
Finish 0
